package org.chiangmeng.hadpediatric

import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import dev.gitlive.firebase.Firebase
import dev.gitlive.firebase.firestore.firestore
import kotlinx.coroutines.flow.first
import kotlinx.coroutines.flow.map
import kotlinx.coroutines.withTimeoutOrNull

class DrugRepository {
    private val db by lazy { Firebase.firestore }

    fun newbornDrugsFlow() = db.collection("NewbornDrugsNew")
        .snapshots
        .map { snapshot -> snapshot.documents.mapNotNull { it.data<NewbornDrug>() } }

    fun pediatricDrugsFlow() = db.collection("PediatricDrugsNew")
        .snapshots
        .map { snapshot -> snapshot.documents.mapNotNull { it.data<PediatricDrug>() } }
}

object NewbornDrugData {
    var NewborndrugList by mutableStateOf<List<NewbornDrug>>(emptyList())
    var isNewbornLoaded by mutableStateOf(false)

    suspend fun init(repository: DrugRepository) {
        if (isNewbornLoaded) return
        
        try {
            // รอข้อมูลไม่เกิน 5 วินาที (จาก Cache หรือ Server)
            // ถ้ามี Cache อยู่แล้ว .first() จะทำงานทันทีและข้ามหน้าหมุนไปได้เลย
            val data = withTimeoutOrNull(5000L) {
                repository.newbornDrugsFlow().first { it.isNotEmpty() }
            }
            if (data != null) {
                NewborndrugList = data
                isNewbornLoaded = true
            }
        } catch (e: Exception) {
            println("Failed to init NewbornDrugs: ${e.message}")
        }
    }
}

object PediatricDrugData {
    var PediatricdrugList by mutableStateOf<List<PediatricDrug>>(emptyList())
    var isLoaded by mutableStateOf(false)

    suspend fun init(repository: DrugRepository) {
        if (isLoaded) return
        
        try {
            val data = withTimeoutOrNull(5000L) {
                repository.pediatricDrugsFlow().first { it.isNotEmpty() }
            }
            if (data != null) {
                PediatricdrugList = data
                isLoaded = true
            }
        } catch (e: Exception) {
            println("Failed to init PediatricDrugs: ${e.message}")
        }
    }
}