@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun DrugListScreen(
    viewModel: DrugViewModel,
    onBack: () -> Unit
) {
    val availableDrugs by viewModel.availableDrugs.collectAsState()
    var showAddDialog by remember { mutableStateOf(false) }
    var isCalculated by remember { mutableStateOf(false) }

    val bgImage =
        if (viewModel.department == Department.Newborn) Res.drawable.newbornbg else Res.drawable.pediatricbg
    val topImage =
        if (viewModel.department == Department.Newborn) Res.drawable.newborntop else Res.drawable.pediatrictop

    Box(modifier = Modifier.fillMaxSize()) {
        Image(
            painter = painterResource(bgImage),
            contentDescription = null,
            modifier = Modifier.fillMaxSize(),
            contentScale = ContentScale.Crop,
            alpha = 0.4f
        )

        Scaffold(
            containerColor = Color.Transparent,
            topBar = {
                Surface(
                    shadowElevation = 4.dp,
                    color = MaterialTheme.colorScheme.surface.copy(alpha = 0.85f)
                ) {
                    Column(modifier = Modifier.fillMaxWidth()) {
                        Box(modifier = Modifier.fillMaxWidth().height(120.dp)) {
                            Image(
                                painter = painterResource(topImage),
                                contentDescription = null,
                                modifier = Modifier.fillMaxSize(),
                                contentScale = ContentScale.Crop
                            )
                            Box(
                                modifier = Modifier
                                    .fillMaxSize()
                                    .background(Color.Black.copy(alpha = 0.2f))
                            )

                            IconButton(
                                onClick = onBack,
                                modifier = Modifier.padding(8.dp).align(Alignment.TopStart)
                            ) {
                                Icon(
                                    Icons.AutoMirrored.Filled.ArrowBack,
                                    contentDescription = "Back",
                                    tint = Color.White
                                )
                            }

                            Text(
                                text = if (viewModel.department == Department.Newborn) "Newborn" else "Pediatrics",
                                style = MaterialTheme.typography.headlineMedium,
                                color = Color.White,
                                fontWeight = FontWeight.ExtraBold,
                                modifier = Modifier.align(Alignment.BottomStart).padding(16.dp)
                            )
                        }

                        Row(
                            modifier = Modifier.fillMaxWidth().padding(16.dp),
                            horizontalArrangement = Arrangement.SpaceBetween,
                            verticalAlignment = Alignment.CenterVertically
                        ) {
                            Column(modifier = Modifier.weight(1f)) {
                                Text(
                                    "Weight (kg)",
                                    style = MaterialTheme.typography.labelMedium,
                                    fontWeight = FontWeight.Bold
                                )
                                EditableWeightField(
                                    value = viewModel.weight.value,
                                    onValueChange = {
                                        viewModel.updateWeight(it)
                                        isCalculated = false // Reset calculation on weight change
                                    }
                                )
                            }
                            Column(horizontalAlignment = Alignment.End) {
                                Text(
                                    "Total Rate (24 hr)",
                                    style = MaterialTheme.typography.labelMedium,
                                    fontWeight = FontWeight.Bold
                                )
                                Text(
                                    "${(viewModel.totalFluidRate * 24).formatNoDotZero()} ml",
                                    style = MaterialTheme.typography.headlineMedium,
                                    fontWeight = FontWeight.Bold,
                                    color = MaterialTheme.colorScheme.primary
                                )
                            }
                        }
                    }
                }
            },
            floatingActionButton = {
                if (!isCalculated) {
                    FloatingActionButton(
                        onClick = { showAddDialog = true },
                        containerColor = MaterialTheme.colorScheme.primary,
                        contentColor = Color.White
                    ) {
                        Text("+", fontSize = 28.sp, fontWeight = FontWeight.Bold)
                    }
                }
            }
        ) { paddingValues ->
            Column(modifier = Modifier.padding(paddingValues).fillMaxSize()) {
                if (viewModel.activeDrugs.isEmpty()) {
                    Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
                        Surface(
                            color = Color.White.copy(alpha = 0.8f),
                            shape = RoundedCornerShape(16.dp)
                        ) {
                            Text(
                                "No drugs added.\nPress + to start.",
                                color = Color.DarkGray,
                                modifier = Modifier.padding(24.dp),
                                style = MaterialTheme.typography.bodyLarge,
                                fontWeight = FontWeight.Bold
                            )
                        }
                    }
                } else {
                    LazyColumn(
                        contentPadding = PaddingValues(16.dp),
                        verticalArrangement = Arrangement.spacedBy(16.dp),
                        modifier = Modifier.weight(1f)
                    ) {
                        items(viewModel.activeDrugs, key = { it.id }) { drug ->
                            SwipeToDeleteContainer(
                                drugName = drug.config.name,
                                onDelete = { viewModel.removeDrug(drug) }
                            ) {
                                DrugCard(
                                    drug = drug,
                                    isCalculated = isCalculated,
                                    onUpdate = { d, v, r, u ->
                                        viewModel.updateDrugCalculation(drug.id, d, v, r, u)
                                        isCalculated = false // Reset calculation on change
                                    }
                                )
                            }
                        }
                    }

                    Button(
                        onClick = { isCalculated = !isCalculated },
                        modifier = Modifier.fillMaxWidth().padding(16.dp),
                        shape = RoundedCornerShape(12.dp),
                        colors = ButtonDefaults.buttonColors(
                            containerColor = if (isCalculated) MaterialTheme.colorScheme.secondary else MaterialTheme.colorScheme.primary
                        )
                    ) {
                        Text(
                            if (isCalculated) "แก้ไขข้อมูล" else "คำนวณผลลัพธ์",
                            fontWeight = FontWeight.Bold
                        )
                    }
                }
            }

            if (showAddDialog) {
                AlertDialog(
                    onDismissRequest = { showAddDialog = false },
                    title = { Text("Select High-Alert Drug", fontWeight = FontWeight.Bold) },
                    text = {
                        Box(modifier = Modifier.heightIn(max = 400.dp)) {
                            LazyColumn {
                                items(availableDrugs) { config ->
                                    ListItem(
                                        headlineContent = {
                                            Text(
                                                config.name,
                                                fontWeight = FontWeight.Bold
                                            )
                                        },
                                        supportingContent = {
                                            val trade = config.tradeName ?: ""
                                            Text(
                                                "$trade (${config.unit})",
                                                style = MaterialTheme.typography.bodySmall
                                            )
                                        },
                                        modifier = Modifier.fillMaxWidth().clickable {
                                            viewModel.addDrug(config)
                                            showAddDialog = false
                                            isCalculated = false
                                        }
                                    )
                                    HorizontalDivider(
                                        thickness = 0.5.dp,
                                        color = Color.LightGray.copy(alpha = 0.5f)
                                    )
                                }
                            }
                        }
                    },
                    confirmButton = {
                        TextButton(onClick = { showAddDialog = false }) {
                            Text(
                                "Close",
                                fontWeight = FontWeight.Bold
                            )
                        }
                    }
                )
            }
        }
    }
}

@Composable
fun DrugCard(
    drug: DrugCalculation,
    isCalculated: Boolean,
    onUpdate: (Double?, Double?, Double?, String?) -> Unit
) {
    val isPeripheralOver = drug.isConcOverPeripheral && drug.config.maxConcPeripheral != null
    val hasCriticalError = drug.isConcOverCentral || drug.isDoseOver || isPeripheralOver
    val displayUnit = if (drug.selectedUnit.isEmpty()) "กรุณาเลือกหน่วย" else drug.selectedUnit

    Card(
        modifier = Modifier.fillMaxWidth(),
        shape = RoundedCornerShape(28.dp),
        elevation = CardDefaults.cardElevation(defaultElevation = 2.dp),
        colors = CardDefaults.cardColors(
            containerColor = if (hasCriticalError)
                Color(0xFFFFEBEE).copy(alpha = 0.95f) else Color.White.copy(alpha = 0.9f)
        )
    ) {
        Column(modifier = Modifier.padding(20.dp)) {
            if (!isCalculated) {
                // Editable Mode (Current Layout)
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Column(modifier = Modifier.weight(1f)) {
                        // 1. ชื่อยา (ฝั่งซ้าย)
                        // 💡 ใช้ weight(1f) ที่ตัว Text เลย เพื่อให้มันกินพื้นที่ฝั่งซ้ายทั้งหมด และดัน Rate ไปขวาสุด
                        Text(
                            text = drug.config.name,
                            style = MaterialTheme.typography.titleLarge,
                            fontWeight = FontWeight.ExtraBold,
                            color = Color(0xFF1E293B),
                            modifier = Modifier.weight(1f)
                        )
                        if (!drug.config.unit2.isNullOrBlank()) {
                            Row(
                                modifier = Modifier.padding(top = 4.dp),
                                horizontalArrangement = Arrangement.spacedBy(8.dp)
                            ) {
                                listOf(drug.config.unit, drug.config.unit2).forEach { unit ->
                                    FilterChip(
                                        selected = drug.selectedUnit == unit,
                                        onClick = { onUpdate(null, null, null, unit) },
                                        label = { Text(unit, fontSize = 11.sp) },
                                        shape = RoundedCornerShape(8.dp)
                                    )
                                }
                            }
                        }
                        // 💡 ใส่ Spacer กั้นไว้เผื่อชื่อยายาวเกินไป จะได้ไม่ไปชนกับตัวเลข Rate ครับ
                        Spacer(modifier = Modifier.width(8.dp))

                        // 2. Rate (ฝั่งขวา)
                        Text(
                            text = "${drug.mlPerHour.formatNoDotZero()} ml/hr",
                            style = MaterialTheme.typography.headlineSmall,
                            fontWeight = FontWeight.ExtraBold,
                            color = MaterialTheme.colorScheme.secondary
                        )
                    }
                }

                if (drug.isDoseOver || drug.isDoseUnder) {
                    Spacer(modifier = Modifier.height(12.dp))
                    Column(
                        modifier = Modifier
                            .fillMaxWidth()
                            .background(Color.Red.copy(alpha = 0.05f), RoundedCornerShape(8.dp))
                            .padding(8.dp),
                        verticalArrangement = Arrangement.spacedBy(4.dp)
                    ) {
                        if (drug.isDoseOver) WarningText("Dose Over Max (${drug.config.maxDose.formatNoDotZero()})")
                        if (drug.isDoseUnder) WarningText("Dose Under Min (${drug.config.minDose.formatNoDotZero()})")
                    }
                }

                Spacer(modifier = Modifier.height(16.dp))

                Row(horizontalArrangement = Arrangement.spacedBy(12.dp)) {
                    EditableField(
                        label = "Dose\n(${drug.selectedUnit})",
                        value = drug.dose,
                        onValueChange = { onUpdate(it, null, null, drug.selectedUnit) },
                        modifier = Modifier.weight(1f),
                        isError = drug.isDoseOver
                    )

                    EditableField(
                        label = "Volume\n(ml)\n",
                        value = drug.volume,
                        onValueChange = { onUpdate(null, it, null, drug.selectedUnit) },
                        modifier = Modifier.weight(1f)
                    )

                    EditableField(
                        label = "Rate\n(ml/hr)\n",
                        value = drug.rate,
                        onValueChange = { onUpdate(null, null, it, drug.selectedUnit) },
                        modifier = Modifier.weight(1f)
                    )
                }

                Spacer(modifier = Modifier.height(12.dp))

                Surface(
                    color = Color.Black.copy(alpha = 0.05f),
                    shape = RoundedCornerShape(8.dp)
                ) {
                    Text(
                        text = "Concentration: ${formatValue(drug.displayConcentration, 3)} ${drug.config.concUnit}",
                        style = MaterialTheme.typography.labelSmall,
                        color = Color.DarkGray,
                        modifier = Modifier.padding(horizontal = 8.dp, vertical = 4.dp),
                        fontWeight = FontWeight.Bold
                    )
                }
                    if (drug.isConcOverCentral || isPeripheralOver) {
                        Spacer(modifier = Modifier.height(4.dp))
                        val concLabel =
                            if (drug.config.maxConcPeripheral == null) "Conc Max" else "Central Line Max"
                        if (drug.isConcOverCentral) WarningText("CRITICAL: $concLabel (${drug.config.maxConc})")

                        drug.config.maxConcPeripheral?.let { maxP ->
                            if (drug.isConcOverPeripheral) WarningText("Conc Over Peripheral Line Max ($maxP)")
                        }
                    }
            } else {
                // Calculated Result Mode (Order Style)
                val textWeight = FontWeight.Bold
                val textDeco = TextDecoration.Underline
                val textSize = 1.1.em

                Column {
                    Text(
                        text = "Order",
                        style = MaterialTheme.typography.titleLarge,
                        color = MaterialTheme.colorScheme.primary,
                        fontWeight = FontWeight.ExtraBold,
                        modifier = Modifier.padding(bottom = 8.dp)
                    )
                    if (drug.selectedUnit.isEmpty()) {
                        Text(
                            "⚠️ กรุณากลับไปเลือกหน่วยยา",
                            color = Color.Red,
                            fontWeight = FontWeight.Bold
                        )
                    } else {
                        Text(buildAnnotatedString {
                            append("en ${drug.config.name} (")
                            val doseColor = if (drug.isDoseOver) Color.Red else Color.Unspecified
                            withStyle(
                                SpanStyle(
                                    fontWeight = textWeight,
                                    textDecoration = textDeco,
                                    fontSize = textSize,
                                    color = doseColor
                                )
                            ) { append(drug.dose.formatNoDotZero()) }
                            append(" ")
                            withStyle(
                                SpanStyle(
                                    fontWeight = textWeight,
                                    textDecoration = textDeco,
                                    fontSize = textSize
                                )
                            ) { append(drug.config.unit) }
                            append(")")
                        })

                        Text(
                            buildAnnotatedString {
                                withStyle(SpanStyle(fontWeight = FontWeight.Bold)) {
                                    append(
                                        "${
                                            formatValue(
                                                drug.displayPrescribeAmount,
                                                2
                                            )
                                        } ${drug.config.prescribeUnit}"
                                    )
                                }
                                append(" + D5W up to ${drug.volume.formatNoDotZero()} ml\n")
                                withStyle(
                                    SpanStyle(
                                        fontWeight = FontWeight.Bold,
                                        color = MaterialTheme.colorScheme.secondary
                                    )
                                ) {
                                    append("IV drip: ${formatValue(drug.mlPerHour, 2)} ml/hr")
                                }
                            },
                            modifier = Modifier.padding(vertical = 4.dp)
                        )

                        HorizontalDivider(Modifier.padding(vertical = 12.dp), thickness = 0.5.dp)

                        Row(verticalAlignment = Alignment.CenterVertically) {
                            Text(
                                "^ ควรระวัง",
                                style = MaterialTheme.typography.titleMedium,
                                color = MaterialTheme.colorScheme.error,
                                fontWeight = FontWeight.Bold
                            )
                        }

                        Spacer(Modifier.height(4.dp))

                        Text(
                            "ความเข้มข้น: ${
                                formatValue(
                                    drug.displayConcentration,
                                    2
                                )
                            } ${drug.config.concUnit}"
                        )

                        if (drug.isConcOverCentral) {
                            val concLabel =
                                if (drug.config.maxConcPeripheral == null) "ความเข้มข้นเกิน!" else "ความเข้มข้น Central line เกิน!"
                            Text(
                                "$concLabel (Max: ${drug.config.maxConc} ${drug.config.concUnit})",
                                color = Color.Red,
                                fontWeight = FontWeight.Bold,
                                style = MaterialTheme.typography.bodySmall
                            )
                        } else if (drug.dose > 0) {
                            val concLabel =
                                if (drug.config.maxConcPeripheral == null) "ความเข้มข้นเหมาะสม" else "ความเข้มข้น Central line เหมาะสม"
                            Text(
                                "$concLabel (Max: ${drug.config.maxConc} ${drug.config.concUnit})",
                                color = Color(0xFF2E7D32),
                                style = MaterialTheme.typography.bodySmall
                            )
                        }

                        drug.config.maxConcPeripheral?.let { maxP ->
                            if (drug.isConcOverPeripheral) {
                                Text(
                                    "ความเข้มข้น Peripheral line เกิน! (Max: $maxP ${drug.config.concUnit})",
                                    color = Color.Red,
                                    fontWeight = FontWeight.Bold,
                                    style = MaterialTheme.typography.bodySmall
                                )
                            } else if (drug.dose > 0) {
                                Text(
                                    "ความเข้มข้น Peripheral line เหมาะสม (Max: $maxP ${drug.config.concUnit})",
                                    color = Color(0xFF2E7D32),
                                    style = MaterialTheme.typography.bodySmall
                                )
                            }
                        }

                        Spacer(Modifier.height(8.dp))
                        Text(buildAnnotatedString {
                            append("ขนาดยา: ")
                            val doseColor = if (drug.isDoseOver) Color.Red else Color.Unspecified
                            withStyle(SpanStyle(fontWeight = FontWeight.Bold, color = doseColor)) {
                                append("${formatValue(drug.dose, 2)} ${drug.config.unit}")
                            }
                        })
                        // ตรวจสอบว่ามีข้อมูลเบื้องต้นครบก่อนแสดงสถานะขนาดยา
                        if (drug.dose > 0) {
                            val isMinUnit = drug.config.unit.contains("min")
                            val statusTextColor = if (!isMinUnit) Color.Red else Color.Unspecified
                            val statusMessage = buildAnnotatedString {
                                when {
                                    drug.isDoseOver -> {
                                        withStyle(
                                            SpanStyle(
                                                color = Color.Red,
                                                fontWeight = FontWeight.Bold
                                            )
                                        ) {
                                            append("ขนาดยาเกิน! (Max: ${drug.config.maxDose} ${drug.config.unit}) ")
                                        }
                                    }

                                    drug.isDoseUnder -> {
                                        withStyle(
                                            SpanStyle(
                                                color = Color(0xFFFFA500),
                                                fontWeight = FontWeight.Bold
                                            )
                                        ) {
                                            append("ขนาดยาน้อยกว่าแนะนำ (Min: ${drug.config.minDose} ${drug.config.unit}) ")
                                        }
                                    }

                                    else -> {
                                        withStyle(
                                            SpanStyle(
                                                color = Color(0xFF2E7D32),
                                                fontWeight = FontWeight.Bold
                                            )
                                        ) {
                                            append("ขนาดยาเหมาะสม (${drug.config.minDose} - ${drug.config.maxDose})")
                                        }
                                        append("\n")
                                    }
                                }

                                // ต่อท้ายด้วยหน่วยที่มี Style พิเศษ (ขีดเส้นใต้/สีแดงตามเงื่อนไขเดิม)
                                withStyle(
                                    SpanStyle(
                                        color = statusTextColor,
                                        fontWeight = textWeight,
                                        textDecoration = textDeco,
                                        fontSize = textSize
                                    )
                                ) {
                                    append(drug.config.unit)
                                }
                            }

                            Text(
                                text = statusMessage,
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(vertical = 4.dp),
                                style = MaterialTheme.typography.bodyMedium,
                                lineHeight = 20.sp // เพิ่มระยะห่างระหว่างบรรทัดให้อ่านง่ายเวลา Font ใหญ่
                            )
                        }
                    }
                }
            }
        }
    }
}

@Composable
fun WarningText(text: String) {
    Row(verticalAlignment = Alignment.CenterVertically) {
        Icon(
            Icons.Default.Warning,
            contentDescription = null,
            tint = Color.Red,
            modifier = Modifier.size(16.dp)
        )
        Spacer(Modifier.width(6.dp))
        Text(text, color = Color.Red, fontSize = 13.sp, fontWeight = FontWeight.ExtraBold)
    }
}

@Composable
fun EditableField(
    label: String,
    value: Double,
    onValueChange: (Double) -> Unit,
    modifier: Modifier = Modifier,
    isError: Boolean = false
) {
    Column(modifier = modifier) {
        Text(
            label,
            style = MaterialTheme.typography.labelSmall,
            fontWeight = FontWeight.Bold,
            color = Color(0xFF475569)
        )
        var textState by remember(value) { mutableStateOf(if (value == 0.0) "" else value.formatNoDotZero()) }

        OutlinedTextField(
            value = textState,
            onValueChange = {
                textState = it
                it.toDoubleOrNull()?.let { v -> onValueChange(v) }
            },
            modifier = Modifier.fillMaxWidth(),
            singleLine = true,
            shape = RoundedCornerShape(12.dp),
            keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Decimal),
            textStyle = MaterialTheme.typography.bodyLarge.copy(
                fontWeight = FontWeight.Bold,
                color = if (isError) Color.Red else Color.Unspecified
            ),
            isError = isError,
            colors = OutlinedTextFieldDefaults.colors(
                unfocusedContainerColor = Color.White,
                focusedContainerColor = Color.White,
                unfocusedBorderColor = Color.LightGray.copy(alpha = 0.5f)
            )
        )
    }
}

@Composable
fun EditableWeightField(value: Double, onValueChange: (Double) -> Unit) {
    var textState by remember(value) { mutableStateOf(if (value == 0.0) "" else value.formatNoDotZero()) }
    OutlinedTextField(
        value = textState,
        onValueChange = {
            textState = it
            it.toDoubleOrNull()?.let { w -> onValueChange(w) }
        },
        modifier = Modifier.width(120.dp),
        singleLine = true,
        shape = RoundedCornerShape(12.dp),
        keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Decimal),
        textStyle = MaterialTheme.typography.headlineMedium.copy(
            fontWeight = FontWeight.Bold,
            color = MaterialTheme.colorScheme.primary
        ),
        colors = OutlinedTextFieldDefaults.colors(
            unfocusedContainerColor = Color.White,
            focusedContainerColor = Color.White
        )
    )
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun SwipeToDeleteContainer(
    drugName: String,
    onDelete: () -> Unit,
    content: @Composable () -> Unit
) {
    var showConfirmDialog by remember { mutableStateOf(false) }

    val dismissState = rememberSwipeToDismissBoxState(
        confirmValueChange = {
            if (it == SwipeToDismissBoxValue.EndToStart) {
                showConfirmDialog = true
                false
            } else {
                false
            }
        }
    )

    LaunchedEffect(showConfirmDialog) {
        if (!showConfirmDialog) {
            dismissState.reset()
        }
    }

    if (showConfirmDialog) {
        AlertDialog(
            onDismissRequest = { showConfirmDialog = false },
            title = { Text("Confirm Removal", fontWeight = FontWeight.Bold) },
            text = { Text("Remove $drugName from the active infusion list?") },
            confirmButton = {
                Button(
                    onClick = {
                        onDelete()
                        showConfirmDialog = false
                    },
                    colors = ButtonDefaults.buttonColors(containerColor = Color.Red)
                ) {
                    Text("Remove", fontWeight = FontWeight.Bold)
                }
            },
            dismissButton = {
                TextButton(onClick = { showConfirmDialog = false }) {
                    Text("Cancel", fontWeight = FontWeight.Bold)
                }
            }
        )
    }

    SwipeToDismissBox(
        state = dismissState,
        enableDismissFromStartToEnd = false,
        backgroundContent = {
            val color by animateColorAsState(
                when (dismissState.targetValue) {
                    SwipeToDismissBoxValue.EndToStart -> Color.Red.copy(alpha = 0.8f)
                    else -> Color.Transparent
                }
            )
            val scale by animateFloatAsState(
                if (dismissState.targetValue == SwipeToDismissBoxValue.Settled) 0.75f else 1f
            )

            Box(
                Modifier
                    .fillMaxSize()
                    .padding(vertical = 4.dp)
                    .background(color, RoundedCornerShape(28.dp))
                    .padding(horizontal = 24.dp),
                contentAlignment = Alignment.CenterEnd
            ) {
                Icon(
                    Icons.Default.Delete,
                    contentDescription = "Delete Icon",
                    modifier = Modifier.scale(scale),
                    tint = Color.White
                )
            }
        },
        content = { content() }
    )
}
