val PediatricLightBlueColorScheme = lightColorScheme(
    primary = Color(0xFF03A9F4),
    onPrimary = Color.White,
    primaryContainer = Color(0xFFE1F5FE),
    onPrimaryContainer = Color(0xFF01579B),
    secondary = Color(0xFF4FC3F7),
    onSecondary = Color.White,
    background = Color(0xFFF8FDFF),
    surface = Color.White,
    onBackground = Color(0xFF1C1B1F),
    onSurface = Color(0xFF1C1B1F),
    tertiary = Color(0xFF0277BD),
    error = Color(0xFFD32F2F)
)

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun SharedDrugApp(
    department: Department,
    onBack: () -> Unit,
    onShowSettings: () -> Unit
) {
    var selectedTab by remember { mutableStateOf(if (department == Department.Newborn) 0 else 1) }
    var selectedDrug by remember { mutableStateOf<Drug?>(null) }
    var selectedUnit by remember { mutableStateOf("") }
    val drugViewModel = remember { DrugViewModel(department) }
    
    val drugList = if (department == Department.Newborn) {
        NewbornDrugData.NewborndrugList.map { it.toDrug() }
    } else {
        PediatricDrugData.PediatricdrugList.map { it.toDrug() }
    }
    
    val colorScheme = if (department == Department.Newborn) 
        lightColorScheme(primary = Color(0xFFE91E63)) 
    else 
        PediatricLightBlueColorScheme

    val headerImage = if (department == Department.Newborn) Res.drawable.newborntop else Res.drawable.pediatrictop
    val backgroundImage = if (department == Department.Newborn) Res.drawable.newbornbg else Res.drawable.pediatricbg
    val title = if (department == Department.Newborn) "Newborns" else "Pediatrics"

    MaterialTheme(
        colorScheme = colorScheme,
        typography = AppSettings.getTypography()
    ) {
        Box(
            modifier = Modifier
                .fillMaxSize()
                .pointerInput(selectedDrug, selectedTab) {
                    awaitEachGesture {
                        val down = awaitFirstDown(pass = PointerEventPass.Initial)
                        val startX = down.position.x
                        if (startX < 120f) {
                            var totalDragX = 0f
                            while (true) {
                                val event = awaitPointerEvent(pass = PointerEventPass.Initial)
                                val change = event.changes.firstOrNull() ?: break
                                if (change.pressed) {
                                    val dragAmount = change.positionChange().x
                                    totalDragX += dragAmount
                                    if (totalDragX > 80f) {
                                        change.consume()
                                        if (selectedDrug != null) {
                                            selectedDrug = null
                                        } else if (selectedTab == 5) {
                                            selectedTab = if (department == Department.Newborn) 0 else 1
                                        } else {
                                            onBack()
                                        }
                                        break
                                    }
                                } else {
                                    break
                                }
                            }
                        }
                    }
                }
        ) {
            if (selectedDrug == null && selectedTab != 5) {
                DrugSelectionScreen(
                    items = drugList,
                    getName = { it.name },
                    getTradeName = { it.tradeName },
                    getDepartment = { it.department },
                    onItemSelected = { drug, unit ->
                        selectedDrug = drug
                        selectedUnit = unit
                    },
                    getUnit = { it.unit },
                    getUnit2 = { it.unit2 },
                    onBack = onBack,
                    title = "${title}Drugs",
                    primaryColor = MaterialTheme.colorScheme.primary,
                    headerImage = painterResource(headerImage),
                    backgroundImage = painterResource(backgroundImage),
                    onShowSettings = onShowSettings,
                    /*extraContent = {
                        Button(
                            onClick = { selectedTab = 5 },
                            modifier = Modifier.fillMaxWidth().padding(horizontal = 16.dp, vertical = 8.dp),
                            shape = RoundedCornerShape(12.dp),
                            colors = ButtonDefaults.buttonColors(containerColor = MaterialTheme.colorScheme.primary)
                        ) {
                            Icon(Icons.Default.LibraryAdd, contentDescription = null)
                            Spacer(Modifier.width(8.dp))
                            Text("Multiple Drugs Infusion", fontWeight = FontWeight.Bold)
                        }
                    }*/
                )
            } else if (selectedTab == 5) {
                DrugListScreen(
                    viewModel = drugViewModel,
                    onBack = { selectedTab = if (department == Department.Newborn) 0 else 1 }
                )
            } else {
                Box(modifier = Modifier.fillMaxSize()) {
                    Image(
                        painter = painterResource(backgroundImage),
                        contentDescription = null,
                        modifier = Modifier.fillMaxSize(),
                        contentScale = ContentScale.FillHeight
                    )
                    Scaffold(
                        containerColor = Color.White.copy(0.5f),
                        topBar = {
                            TopAppBar(
                                title = {
                                    Row(verticalAlignment = Alignment.CenterVertically) {
                                        Image(
                                            painter = painterResource(headerImage),
                                            contentDescription = null,
                                            modifier = Modifier.size(80.dp).padding(end = 8.dp),
                                            contentScale = ContentScale.Fit
                                        )
                                        Text(
                                            text = title,
                                            style = MaterialTheme.typography.headlineLarge,
                                            color = Color(0xFF263238),
                                            fontWeight = FontWeight.Bold
                                        )
                                    }
                                },
                                colors = TopAppBarDefaults.topAppBarColors(containerColor = Color.Transparent),
                                navigationIcon = {
                                    IconButton(onClick = { selectedDrug = null }) {
                                        Icon(Icons.AutoMirrored.Filled.ArrowBack, contentDescription = "Back")
                                    }
                                },
                                actions = {
                                    IconButton(onClick = onShowSettings) {
                                        Icon(Icons.Default.FormatSize, contentDescription = "Font Size", tint = Color.Gray)
                                    }
                                }
                            )
                        },
                        bottomBar = {
                            NavigationBar(
                                containerColor = Color.White,
                                tonalElevation = 8.dp,
                                windowInsets = WindowInsets(0.dp)
                            ) {
                                if (department == Department.Newborn) {
                                    NavigationBarItem(
                                        selected = selectedTab == 0,
                                        onClick = { selectedTab = 0 },
                                        label = { Text("คำนวณ\nRuleof6", textAlign = TextAlign.Center, style = MaterialTheme.typography.labelSmall) },
                                        icon = { Icon(Icons.Default.Calculate, contentDescription = null) },
                                        colors = NavigationBarItemDefaults.colors(
                                            selectedIconColor = Color(0xFFE65100),
                                            selectedTextColor = Color(0xFFE65100),
                                            indicatorColor = Color(0xFFFFE0B2)
                                        )
                                    )
                                }
                                NavigationBarItem(
                                    selected = selectedTab == 1,
                                    onClick = { selectedTab = 1 },
                                    label = { Text("คำนวณ\nปริมาณยา", textAlign = TextAlign.Center, style = MaterialTheme.typography.labelSmall) },
                                    icon = { Icon(Icons.Default.Science, contentDescription = null) },
                                    colors = NavigationBarItemDefaults.colors(
                                        selectedIconColor = Color(0xFFD32F2F),
                                        selectedTextColor = Color(0xFFD32F2F),
                                        indicatorColor = Color(0xFFFFEBEE)
                                    )
                                )
                                NavigationBarItem(
                                    selected = selectedTab == 2,
                                    onClick = { selectedTab = 2 },
                                    label = { Text("คำนวณ\nDose", textAlign = TextAlign.Center, style = MaterialTheme.typography.labelSmall) },
                                    icon = { Icon(Icons.Default.MedicalServices, contentDescription = null) },
                                    colors = NavigationBarItemDefaults.colors(
                                        selectedIconColor = Color(0xFF388E3C),
                                        selectedTextColor = Color(0xFF388E3C),
                                        indicatorColor = Color(0xFFE8F5E9)
                                    )
                                )
                                NavigationBarItem(
                                    selected = selectedTab == 3,
                                    onClick = { selectedTab = 3 },
                                    label = { Text("คำนวณ\nVolume", textAlign = TextAlign.Center, style = MaterialTheme.typography.labelSmall) },
                                    icon = { Icon(Icons.Default.Opacity, contentDescription = null) },
                                    colors = NavigationBarItemDefaults.colors(
                                        selectedIconColor = Color(0xFF7B1FA2),
                                        selectedTextColor = Color(0xFF7B1FA2),
                                        indicatorColor = Color(0xFFF3E5F5)
                                    )
                                )
                                NavigationBarItem(
                                    selected = selectedTab == 4,
                                    onClick = { selectedTab = 4 },
                                    label = { Text("ข้อมูล\nยา", textAlign = TextAlign.Center, style = MaterialTheme.typography.labelSmall) },
                                    icon = { Icon(Icons.AutoMirrored.Filled.MenuBook, contentDescription = null) },
                                    colors = NavigationBarItemDefaults.colors(
                                        selectedIconColor = Color(0xFF00796B),
                                        selectedTextColor = Color(0xFF00796B),
                                        indicatorColor = Color(0xFFE0F2F1)
                                    )
                                )
                            }
                        }
                    ) { innerPadding ->
                        Box(modifier = Modifier.padding(innerPadding)) {
                            when (selectedTab) {
                                0 -> if (department == Department.Newborn) GenericCalcRuleOfSixScreen(selectedDrug!!, selectedUnit, department)
                                1 -> GenericCalcPrescribeScreen(selectedDrug!!, selectedUnit, department)
                                2 -> GenericCalcDoseScreen(selectedDrug!!, selectedUnit, department)
                                3 -> GenericCalcVolumeScreen(selectedDrug!!, selectedUnit, department)
                                4 -> {
                                    GenericDrugDetailReferenceScreen(
                                        selectedDrug = selectedDrug!!,
                                        selectedUnit = selectedUnit,
                                        allDrugs = drugList
                                    )
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}
