// 1. สร้าง Enum ไว้ที่นี่ เพื่อให้ไฟล์อื่น (เช่น app.kt) เรียกใช้ได้
enum class Department(
    val label: String,
    val description: String,
    val color: Color,
    val backgroundColor: Color,
    val icon: ImageVector
) {
    Pediatric(
        label = "Pediatrics",
        description = "",
        color = Color(0xFF1976D2),
        backgroundColor = Color(0xFFE3F2FD),
        icon = Icons.Default.EscalatorWarning
    ),
    Newborn(
        label = "Newborn",
        description = "",
        color = Color(0xFFC2185B),
        backgroundColor = Color(0xFFFCE4EC),
        icon = Icons.Default.ChildCare
    )
}

@Composable
fun SelectionScreen(onDepartmentSelected: (Department) -> Unit) {
    var hasAcceptedDisclaimer by remember { mutableStateOf(false) }
    val settings = remember { Settings() }
    var showDisclaimer by remember { mutableStateOf(true) }
    LaunchedEffect(Unit) {
        try {
            val db = Firebase.firestore
            // ทำทั้ง 2 Collection เลยครับคุณหมอ จะได้จบในทีเดียว
            val collections = listOf("PediatricDrugsNew", "NewbornDrugsNew")

            collections.forEach { collectionName ->
                val snapshot = db.collection(collectionName).get()
                snapshot.documents.forEach { doc ->
                    // ใช้โครงสร้าง "field" to value สำหรับ GitLive SDK
                    doc.reference.update("unit2" to null)
                }
            }
            println("✅ [Migration] อัปเกรด unit2 ให้ยาทุกตัวสำเร็จแล้วครับ!")
        } catch (e: Exception) {
            println("❌ [Migration] เกิดข้อผิดพลาด: ${e.message}")
        }
    }
    Box(modifier = Modifier.fillMaxSize()) {

        // 2. ใส่ภาพ Background
        Image(
            painter = painterResource(Res.drawable.openbg), // เปลี่ยนเป็นชื่อไฟล์ภาพของคุณ
            contentDescription = null,
            modifier = Modifier.fillMaxSize(),
            contentScale = ContentScale.FillHeight
        )
        Surface(
            modifier = Modifier.fillMaxSize(),
            color = Color.Transparent
        ) {
            Column(
                modifier = Modifier
                    .fillMaxSize()
                    .padding(10.dp),
                horizontalAlignment = Alignment.CenterHorizontally
            ) {
                // --- ส่วนหัวแอป ---
                // --- Logo and Title Section ---
                // --- Logo and Title Section ---
                Column(
                    horizontalAlignment = Alignment.CenterHorizontally,
                    modifier = Modifier.fillMaxWidth() // ให้กว้างเต็มพื้นที่เพื่อจัดกึ่งกลางได้สวยงาม
                ) {
                    // ส่วนบน: รูป + Title
                    Row(
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.Center,
                        modifier = Modifier.padding(top = 8.dp)
                    ) {
                        Image(
                            painter = painterResource(Res.drawable.childrenhospitallogo),
                            contentDescription = "Hospital Logo",
                            modifier = Modifier.size(60.dp), // ปรับขนาดรูปลงเล็กน้อยให้รับกับ Text
                            contentScale = ContentScale.Fit
                        )

                        Spacer(modifier = Modifier.width(8.dp)) // ระยะห่างระหว่างรูปกับตัวหนังสือ

                        Text(
                            text = "HADPediatrics",
                            style = MaterialTheme.typography.headlineLarge
                        )
                    }

                    // ส่วนล่าง: Subtitle
                    Text(
                        text = "QSNICH High-Alert Medications Calculator",
                        style = MaterialTheme.typography.labelSmall,
                        color = MaterialTheme.colorScheme.secondary,
                        modifier = Modifier.padding(top = 4.dp, bottom = 8.dp)
                    )
                }

                Spacer(modifier = Modifier.weight(1f))
                DepartmentCard(
                    dept = Department.Newborn,
                    isImageLeft = true,
                    onClick = { onDepartmentSelected(Department.Newborn) }
                )

                Spacer(modifier = Modifier.height(20.dp))


                DepartmentCard(
                    dept = Department.Pediatric,
                    isImageLeft = false,
                    onClick = { onDepartmentSelected(Department.Pediatric) }
                )

                Spacer(modifier = Modifier.weight(1f)) // ผลัก Credit ลงไปด้านล่างสุด

                // --- 3. ส่วนอ้างอิง (Footer) ---
                FooterSection()
            }
        }

        if (showDisclaimer) {
            DisclaimerDialog(
                onAccept = {
                    // 3. ซ่อน Dialog ทันทีที่ผู้ใช้กดปุ่ม
                    showDisclaimer = false

                    // 4. บันทึกค่าลงในเครื่องว่าผู้ใช้ยอมรับแล้ว
                    settings.putBoolean("disclaimer_accepted", true)
                }
            )
        }

    }
}

@Composable
fun DepartmentCard(dept: Department, isImageLeft: Boolean, onClick: () -> Unit) {
    Card(
        onClick = onClick,
        modifier = Modifier
            .fillMaxWidth()
            .height(140.dp),
        shape = RoundedCornerShape(24.dp),
        colors = CardDefaults.cardColors(containerColor = dept.backgroundColor.copy(alpha = 1.0f)), // ใช้สีพื้นหลังจางๆ
        border = BorderStroke(1.dp, dept.color.copy(alpha = 0.3f)) // มีกรอบรวมตามที่ต้องการ
    ) {
        Row(
            modifier = Modifier.fillMaxSize().padding(8.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            if (isImageLeft) {
                Box(
                    modifier = Modifier.weight(0.35f),
                    contentAlignment = Alignment.Center
                ) {
                    DepartmentImage(Res.drawable.newborn)
                }
                Spacer(modifier = Modifier.width(16.dp))
                DepartmentInfo(
                    dept.label,
                    "Calculation of high-alert medications for neonates (≤ 1 month of age)",
                    Alignment.Start,
                    Modifier.weight(0.65f)
                )
            } else {
                DepartmentInfo(
                    dept.label,
                    "Calculation of high-alert medications for infants and children (> 1 month of age)",
                    Alignment.End,
                    Modifier.weight(0.65f)
                )
                Spacer(modifier = Modifier.width(16.dp))
                Box(
                    modifier = Modifier.weight(0.35f),
                    contentAlignment = Alignment.Center
                ) {
                    DepartmentImage(Res.drawable.pediatric)
                }
            }
        }
    }
}

@Composable
fun DepartmentImage(imageName: DrawableResource) {
    Image(
        painter = painterResource(imageName),
        contentDescription = null,
        contentScale = ContentScale.Fit,
        modifier = Modifier
            .size(160.dp)
    )
}

@Composable
fun DepartmentInfo(
    title: String,
    subtitle: String,
    align: Alignment.Horizontal,
    modifier: Modifier = Modifier,
    textColor: Color = Color.Black
) {
    Column(
        modifier = modifier,
        horizontalAlignment = align,
        verticalArrangement = Arrangement.Top
    ) {
        Text(
            text = title,
            style = MaterialTheme.typography.headlineLarge,
            color = textColor,
            maxLines = 1,
            softWrap = false,
            textAlign = TextAlign.Center,
            modifier = Modifier.fillMaxWidth()
        )
        Text(text = subtitle, style = MaterialTheme.typography.bodySmall, color = Color.Black)
    }
}

