package org.chiangmeng.hadpediatric

import androidx.compose.material3.Typography
import androidx.compose.runtime.Composable
import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import androidx.compose.ui.text.TextStyle
import androidx.compose.ui.text.font.FontFamily
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.unit.sp
import com.russhwolf.settings.Settings
import hadpediatric.composeapp.generated.resources.Res
import hadpediatric.composeapp.generated.resources.comicneue_bold
import hadpediatric.composeapp.generated.resources.comicneue_regular
import hadpediatric.composeapp.generated.resources.mali_bold
import hadpediatric.composeapp.generated.resources.mali_regular
import org.jetbrains.compose.resources.Font

object AppSettings {
    private val settings: Settings = Settings()
    private const val FONT_SIZE_KEY = "font_size_multiplier"

    var fontSizeMultiplier by mutableStateOf(settings.getFloat(FONT_SIZE_KEY, 1.0f))
        private set

    fun updateFontSizeMultiplier(multiplier: Float) {
        fontSizeMultiplier = multiplier
        settings.putFloat(FONT_SIZE_KEY, multiplier)
    }

    @Composable
    fun getTypography(): Typography {
        val multiplier = fontSizeMultiplier
        val appFontFamily = FontFamily(
            Font(Res.font.mali_regular, FontWeight.Normal),
            Font(Res.font.mali_bold, FontWeight.Bold),
            Font(Res.font.comicneue_regular, FontWeight.Normal),
            Font(Res.font.comicneue_bold, FontWeight.Bold)
        )

        return Typography(
            bodyLarge = TextStyle(fontFamily = appFontFamily, fontSize = (20 * multiplier).sp),
            bodyMedium = TextStyle(fontFamily = appFontFamily, fontSize = (18 * multiplier).sp),
            bodySmall = TextStyle(fontFamily = appFontFamily, fontSize = (16 * multiplier).sp),
            titleLarge = TextStyle(
                fontFamily = appFontFamily,
                fontWeight = FontWeight.Bold,
                fontSize = (22 * multiplier).sp
            ),
            titleMedium = TextStyle(
                fontFamily = appFontFamily,
                fontWeight = FontWeight.SemiBold,
                fontSize = (16 * multiplier).sp
            ),
            titleSmall = TextStyle(
                fontFamily = appFontFamily,
                fontWeight = FontWeight.Medium,
                fontSize = (14 * multiplier).sp
            ),
            labelLarge = TextStyle(
                fontFamily = appFontFamily,
                fontWeight = FontWeight.Medium,
                fontSize = (14 * multiplier).sp
            ),
            labelMedium = TextStyle(fontFamily = appFontFamily, fontSize = (16 * multiplier).sp),
            labelSmall = TextStyle(fontFamily = appFontFamily, fontSize = (14 * multiplier).sp),
            headlineLarge = TextStyle(
                fontFamily = appFontFamily,
                fontWeight = FontWeight.Bold,
                fontSize = (32 * multiplier).sp
            ),
            headlineMedium = TextStyle(
                fontFamily = appFontFamily,
                fontWeight = FontWeight.Bold,
                fontSize = (28 * multiplier).sp
            ),
            headlineSmall = TextStyle(
                fontFamily = appFontFamily,
                fontWeight = FontWeight.Bold,
                fontSize = (24 * multiplier).sp
            )
        )
    }
}
