// Helper class to map different results to a common interface for the screens
data class CalculationResultAdapter(
    val displayPrescribe: Double = 0.0,
    val rate: Double = 0.0,
    val displayConc: Double = 0.0,
    val displayDose: Double = 0.0,
    val volumeMl: Double = 0.0,
    val isDoseOver: Boolean = false,
    val isDoseUnder: Boolean = false,
    val isConcOverCentral: Boolean = false,
    val isConcOverPeripheral: Boolean = false,
    val isAllDataPresent: Boolean = false,
    val doseForMaxConc: Double = 0.0,
    val doseForMaxPeripheralConc: Double = 0.0,
    val concUnitFactor: Double = 1.0,
    val displayMaxDose: Double = 0.0,
    val displayMinDose: Double = 0.0,
    val selectedUnit: String = ""
)

fun NewbornCalculationResult.toAdapter() = CalculationResultAdapter(
    displayPrescribe = displayPrescribe,
    rate = rate,
    displayConc = displayConc,
    displayDose = displayDose,
    volumeMl = volumeMl,
    isDoseOver = isDoseOver,
    isDoseUnder = isDoseUnder,
    isConcOverCentral = isConcOverCentral,
    isConcOverPeripheral = isConcOverPeripheral,
    isAllDataPresent = isAllDataPresent,
    doseForMaxConc = doseForMaxConc,
    doseForMaxPeripheralConc = doseForMaxPeripheralConc,
    concUnitFactor = concUnitFactor,
    selectedUnit = this.selectedUnit,
    displayMaxDose = this.displayMaxDose,
    displayMinDose = this.displayMinDose
)

fun PediatricCalculationResult.toAdapter() = CalculationResultAdapter(
    displayPrescribe = displayPrescribe,
    rate = rate,
    displayConc = displayConc,
    displayDose = dose,
    volumeMl = volumeMl,
    isDoseOver = isDoseOver,
    isDoseUnder = isDoseUnder,
    isConcOverCentral = isConcOverCentral,
    isConcOverPeripheral = isConcOverPeripheral,
    isAllDataPresent = isAllDataPresent,
    doseForMaxConc = doseForMaxConc,
    doseForMaxPeripheralConc = doseForMaxPeripheralConc,
    concUnitFactor = concUnitFactor,
    selectedUnit = this.selectedUnit,
    displayMaxDose = this.displayMaxDose,
    displayMinDose = this.displayMinDose
)

@Composable
fun GenericDrugLabel(name: String, tradeName: String?, department: Department) {
    Surface(
        modifier = Modifier.fillMaxWidth().padding(vertical = 8.dp),
        shape = RoundedCornerShape(12.dp),
        border = BorderStroke(4.dp, department.color),
        color = Color.White,
        shadowElevation = 2.dp
    ) {
        val displayName = if (tradeName.isNullOrBlank()) name else "$name ($tradeName)"
        Text(
            text = displayName,
            modifier = Modifier.padding(16.dp),
            style = MaterialTheme.typography.headlineSmall,
            fontWeight = FontWeight.Bold,
            color = Color.Black,
            textAlign = TextAlign.Center
        )
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun GenericCalcPrescribeScreen(selectedDrug: Drug, selectedUnit: String, department: Department) {
    var selectedRate by remember { mutableStateOf(" ") }
    var showDialog by remember { mutableStateOf(false) }
    var showTable by remember { mutableStateOf(false) }
    val focusManager = LocalFocusManager.current
    var weightStr by remember { mutableStateOf(" ") }
    var doseStr by remember { mutableStateOf(" ") }
    var volumeStr by remember { mutableStateOf(" ") }

    val weight = weightStr.toDoubleOrNull() ?: 0.0
    val doseInput = doseStr.toDoubleOrNull() ?: 0.0
    val selectedVolume = volumeStr.toDoubleOrNull() ?: 0.0
    val rateHrInput = selectedRate.toDoubleOrNull() ?: 0.0
    val rateHrForLimit = if (rateHrInput > 0) rateHrInput else 1.0

    val result = remember(
        selectedDrug,
        selectedUnit,
        weight,
        doseInput,
        rateHrInput,
        selectedVolume,
        department
    ) {
        if (department == Department.Newborn) {
            NewbornCalculator.NewbornCalcPrescribeScreen(
                selectedDrug.toNewbornDrug(),
                selectedUnit,
                weight,
                doseInput,
                rateHrInput,
                selectedVolume
            ).toAdapter()
        } else {
            PediatricCalculator.PediatricCalcPrescribeScreen(
                selectedDrug.toPediatricDrug(),
                selectedUnit,
                weight,
                doseInput,
                rateHrInput,
                selectedVolume
            ).toAdapter()
        }
    }

    // คำนวณขนาดยาสูงสุดแยกต่างหากเพื่อให้แสดงผลได้แม้ยังไม่กรอก Rate (ใช้ Rate = 1.0 เป็นฐาน)
    val limitResult = remember(selectedDrug, selectedUnit, weight, rateHrForLimit, department) {
        if (department == Department.Newborn) {
            NewbornCalculator.NewbornCalcPrescribeScreen(
                selectedDrug.toNewbornDrug(),
                selectedUnit,
                weight,
                0.0,
                rateHrForLimit,
                25.0
            ).toAdapter()
        } else {
            PediatricCalculator.PediatricCalcPrescribeScreen(
                selectedDrug.toPediatricDrug(),
                selectedUnit,
                weight,
                0.0,
                rateHrForLimit,
                25.0
            ).toAdapter()
        }
    }

    LaunchedEffect(selectedDrug) {
        weightStr = " "; doseStr = " "; volumeStr = " "; selectedRate = " "
    }

    val textFieldColors = OutlinedTextFieldDefaults.colors(
        focusedContainerColor = Color.White,
        unfocusedContainerColor = Color.White,
        errorContainerColor = Color(0xFFFFEBEE)
    )

    Column(
        modifier = Modifier.padding(4.dp).fillMaxSize()
            .windowInsetsPadding(WindowInsets.systemBars)
            .pointerInput(Unit) { detectTapGestures { focusManager.clearFocus() } }
            .verticalScroll(rememberScrollState())
    ) {
        Text(
            "คำนวณ ปริมาณยา",
            style = MaterialTheme.typography.titleLarge,
            fontWeight = FontWeight.Bold
        )
        HorizontalDivider()
        Spacer(Modifier.height(8.dp))
        GenericDrugLabel(selectedDrug.name, selectedDrug.tradeName, department)
        Spacer(Modifier.height(8.dp))
        OutlinedTextField(
            value = weightStr,
            onValueChange = { weightStr = it },
            label = { Text("น้ำหนัก(kg)") },
            keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Decimal),
            modifier = Modifier.fillMaxWidth(),
            colors = textFieldColors
        )
        Spacer(Modifier.height(12.dp))

        OutlinedTextField(
            value = doseStr,
            onValueChange = { doseStr = it },
            label = { Text("ขนาดยา (${if (selectedUnit.isBlank()) "เลือกหน่วยก่อน" else selectedUnit})") },
            keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Decimal),
            modifier = Modifier.fillMaxWidth(),
            colors = textFieldColors,
            isError = result.isDoseOver,
            textStyle = LocalTextStyle.current.copy(color = if (result.isDoseOver) Color.Red else Color.Unspecified),
        )

        if (rateHrInput > 0) {
            Column {
                val centralLabel =
                    if (selectedDrug.maxConcPeripheral != null) " (Central line)" else ""
                Text(
                    "ขนาดยา ${
                        formatValue(
                            limitResult.doseForMaxConc,
                            2
                        )
                    } (${result.selectedUnit}) จะให้ความเข้มข้นสูงสุด$centralLabel ${
                        formatValue(
                            selectedDrug.maxConcCentral,
                            2
                        )
                    } (${selectedDrug.concUnit})",
                    color = Color.Blue,
                    style = MaterialTheme.typography.bodySmall
                )
                if (selectedDrug.maxConcPeripheral != null) {
                    Text(
                        "ขนาดยา ${
                            formatValue(
                                limitResult.doseForMaxPeripheralConc,
                                2
                            )
                        } (${result.selectedUnit}) จะให้ความเข้มข้นสูงสุด (Peripheral line) ${
                            formatValue(
                                selectedDrug.maxConcPeripheral,
                                2
                            )
                        } (${selectedDrug.concUnit})",
                        color = Color(0xFF00796B),
                        style = MaterialTheme.typography.bodySmall
                    )
                }
            }
        }

        Spacer(Modifier.height(8.dp))
        if (result.isDoseOver) Text(
            "ขนาดยาเกิน (Max: ${
                formatValue(
                    result.displayMaxDose,
                    2
                )
            } ${result.selectedUnit})",
            color = Color.Red,
            style = MaterialTheme.typography.bodySmall
        )
        if (result.isDoseUnder) Text(
            "ขนาดยาน้อยกว่าแนะนำ (Min: ${
                formatValue(
                    result.displayMinDose,
                    2
                )
            } ${result.selectedUnit})",
            color = Color(0xFFFFA500),
            style = MaterialTheme.typography.bodySmall
        )

        Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(8.dp)) {
            OutlinedTextField(
                value = volumeStr,
                onValueChange = { volumeStr = it },
                label = { Text("ปริมาณสารน้ำ (ml)") },
                keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Decimal),
                modifier = Modifier.weight(1f),
                colors = textFieldColors
            )
            OutlinedTextField(
                value = selectedRate,
                onValueChange = { selectedRate = it },
                label = { Text("Rate (ml/hr)") },
                keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Decimal),
                modifier = Modifier.weight(1f),
                colors = textFieldColors
            )
        }

        Spacer(Modifier.height(16.dp))
        Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(8.dp)) {
            Button(
                onClick = { showDialog = true },
                modifier = Modifier.weight(1f),
                enabled = result.isAllDataPresent
            ) {
                Text("คำนวณผลลัพธ์")
            }
            OutlinedButton(onClick = { showTable = !showTable }, modifier = Modifier.weight(1f)) {
                Text(text = if (showTable) "ซ่อนตาราง" else "ดูตารางเพิ่มลดยา")
            }
        }

        if (showTable) {
            if (department == Department.Newborn) {
                NewbornRateDoseTable(
                    selectedDrug.toNewbornDrug(),
                    selectedUnit,
                    weight,
                    selectedVolume,
                    result.rate,
                    result.displayPrescribe
                )
            } else {
                PediatricRateDoseTable(
                    selectedDrug.toPediatricDrug(),
                    selectedUnit,
                    weight,
                    selectedVolume,
                    result.rate,
                    result.displayPrescribe
                )
            }
        }

        if (showDialog) {
            ResultDialog(
                result,
                selectedDrug,
                doseInput,
                selectedVolume,
                rateHrInput,
                onDismiss = { showDialog = false })
        }
    }
}

@Composable
fun ResultDialog(
    result: CalculationResultAdapter,
    selectedDrug: Drug,
    doseInput: Double,
    selectedVolume: Double,
    rateHr: Double,
    onDismiss: () -> Unit
) {
    AlertDialog(
        onDismissRequest = onDismiss,
        title = { Text("Order", fontWeight = FontWeight.Bold) },
        text = {
            // ดึง Style เดิมมาใช้
            val textWeight = FontWeight.Normal
            val textDeco = TextDecoration.Underline
            val textSize = 1.1.em

            Column {
                Text(buildAnnotatedString {
                    append("${selectedDrug.name} (")
                    withStyle(
                        SpanStyle(
                            fontWeight = textWeight,
                            textDecoration = textDeco,
                            fontSize = textSize
                        )
                    ) {
                        append("$doseInput")
                    } // 👈 ใช้ doseInput ตามที่พยาบาลกรอก
                    append(" ")
                    withStyle(
                        SpanStyle(
                            fontWeight = textWeight,
                            textDecoration = textDeco,
                            fontSize = textSize
                        )
                    ) { append(result.selectedUnit) }
                    append(")")
                })

                Text(
                    buildAnnotatedString {
                        withStyle(SpanStyle(fontWeight = FontWeight.Bold)) {
                            append(
                                "${
                                    formatValue(
                                        result.displayPrescribe,
                                        2
                                    )
                                } ${selectedDrug.prescribeUnit}"
                            )
                        }
                        append(" + D5W up to $selectedVolume ml\n") // 👈 ใช้ selectedVolume
                        withStyle(SpanStyle(fontWeight = textWeight)) {
                            append("IV drip: ${formatValue(result.rate, 2)} ml/hr")
                        }
                    },
                    modifier = Modifier.padding(vertical = 4.dp)
                )

                HorizontalDivider(Modifier.padding(vertical = 12.dp), thickness = 0.5.dp)

                Row(verticalAlignment = Alignment.CenterVertically) {
                    Text(
                        "ควรระวัง",
                        style = MaterialTheme.typography.titleLarge,
                        color = MaterialTheme.colorScheme.error,
                        fontWeight = FontWeight.Bold
                    )
                }

                Spacer(Modifier.height(4.dp))

                Text(
                    "ความเข้มข้น: ${formatValue(result.displayConc, 2)} ${selectedDrug.concUnit}"
                )

                // เช็คความเข้มข้น Central
                if (result.isConcOverCentral) {
                    val concLabel =
                        if (selectedDrug.maxConcPeripheral == null) "ความเข้มข้นเกิน!" else "ความเข้มข้น Central line เกิน!"
                    Text(
                        "$concLabel (Max: ${selectedDrug.maxConcCentral} ${selectedDrug.concUnit})",
                        color = Color.Red,
                        fontWeight = FontWeight.Bold,
                        style = MaterialTheme.typography.bodySmall
                    )
                } else if (result.displayDose > 0) {
                    val concLabel =
                        if (selectedDrug.maxConcPeripheral == null) "ความเข้มข้นเหมาะสม" else "ความเข้มข้น Central line เหมาะสม"
                    Text(
                        "$concLabel (Max: ${selectedDrug.maxConcCentral} ${selectedDrug.concUnit})",
                        color = Color(0xFF2E7D32),
                        style = MaterialTheme.typography.bodySmall
                    )
                }

                // เช็คความเข้มข้น Peripheral
                selectedDrug.maxConcPeripheral?.let { maxP ->
                    if (result.isConcOverPeripheral) {
                        Text(
                            "ความเข้มข้น Peripheral line เกิน! (Max: $maxP ${selectedDrug.concUnit})",
                            color = Color.Red,
                            fontWeight = FontWeight.Bold,
                            style = MaterialTheme.typography.bodySmall
                        )
                    } else if (result.displayDose > 0) {
                        Text(
                            "ความเข้มข้น Peripheral line เหมาะสม (Max: $maxP ${selectedDrug.concUnit})",
                            color = Color(0xFF2E7D32),
                            style = MaterialTheme.typography.bodySmall
                        )
                    }
                }

                Spacer(Modifier.height(8.dp))

                Text(buildAnnotatedString {
                    append("ขนาดยา: ")
                    val doseColor = if (result.isDoseOver) Color.Red else Color.Unspecified
                    withStyle(SpanStyle(fontWeight = textWeight, color = doseColor)) {
                        val doseVal =
                            if (result.displayDose > 0) formatValue(result.displayDose, 2) else " "
                        append("$doseVal ${result.selectedUnit}")
                    }
                })

                // ตรวจสอบสถานะขนาดยา (Over, Under, Normal)
                if (result.displayDose > 0) {
                    val isMinUnit = result.selectedUnit.contains("min")
                    val statusTextColor = if (!isMinUnit) Color.Red else Color.Unspecified
                    val statusTextStyle = if (!isMinUnit) FontWeight.Bold else FontWeight.Normal
                    val currentColor = when {
                        result.isDoseOver -> Color.Red
                        result.isDoseUnder -> Color(0xFFFFA500)
                        else -> Color(0xFF2E7D32)
                    }
                    val currentStyle = when {
                        result.isDoseOver -> FontWeight.Bold
                        result.isDoseUnder -> FontWeight.Bold
                        else -> textWeight
                    }
                    val statusMessage = buildAnnotatedString {
                        withStyle(SpanStyle(color = currentColor, fontWeight = currentStyle)) {
                            when {
                                result.isDoseOver -> {
                                    append(
                                        "ขนาดยาเกิน! (Max: ${
                                            formatValue(
                                                result.displayMaxDose,
                                                2
                                            )
                                        }"
                                    )
                                }

                                result.isDoseUnder -> {
                                    append(
                                        "ขนาดยาน้อยกว่าแนะนำ (Min: ${
                                            formatValue(
                                                result.displayMinDose,
                                                2
                                            )
                                        }"
                                    )
                                }

                                else -> {
                                    append("ขนาดยาเหมาะสม (${result.displayMinDose} - ${result.displayMaxDose}")
                                }
                            }
                        }

                        append("\n")
                        withStyle(
                            SpanStyle(
                                color = currentColor,
                                fontWeight = currentStyle,
                                textDecoration = textDeco,
                                fontSize = textSize
                            )
                        ) {
                            append("${result.selectedUnit})")
                        }
                    }

                    Text(
                        text = statusMessage,
                        modifier = Modifier.fillMaxWidth().padding(vertical = 4.dp),
                        style = MaterialTheme.typography.bodyMedium,
                        lineHeight = 20.sp
                    )
                }
            }
        },
        confirmButton = {
            Button(onClick = onDismiss) {
                Text("ตกลง", fontWeight = FontWeight.Bold)
            }
        }
    )
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun GenericCalcDoseScreen(selectedDrug: Drug, selectedUnit: String, department: Department) {
    var prescribeInputStr by remember { mutableStateOf(" ") }
    var weightStr by remember { mutableStateOf(" ") }
    var volumeStr by remember { mutableStateOf(" ") }
    var rateStr by remember { mutableStateOf(" ") }
    var showDialog by remember { mutableStateOf(false) }
    var showTable by remember { mutableStateOf(false) }
    val focusManager = LocalFocusManager.current

    val weight = weightStr.toDoubleOrNull() ?: 0.0
    val prescribeInput = prescribeInputStr.toDoubleOrNull() ?: 0.0
    val volume = volumeStr.toDoubleOrNull() ?: 0.0
    val rate = rateStr.toDoubleOrNull() ?: 0.0

    val result =
        remember(selectedDrug, selectedUnit, weight, prescribeInput, volume, rate, department) {
            if (department == Department.Newborn) {
                NewbornCalculator.NewbornCalcDoseScreen(
                    selectedDrug.toNewbornDrug(),
                    selectedUnit,
                    weight,
                    prescribeInput,
                    rate,
                    volume
                ).toAdapter()
            } else {
                PediatricCalculator.PediatricCalcDoseScreen(
                    selectedDrug.toPediatricDrug(),
                    selectedUnit,
                    weight,
                    prescribeInput,
                    rate,
                    volume
                ).toAdapter()
            }
        }

    LaunchedEffect(selectedDrug) {
        weightStr = " "; prescribeInputStr = " "; volumeStr = " "; rateStr = " "
    }

    val textFieldColors = OutlinedTextFieldDefaults.colors(
        focusedContainerColor = Color.White,
        unfocusedContainerColor = Color.White,
        errorContainerColor = Color(0xFFFFEBEE)
    )

    Column(
        modifier = Modifier.padding(4.dp).fillMaxSize()
            .windowInsetsPadding(WindowInsets.systemBars)
            .pointerInput(Unit) { detectTapGestures { focusManager.clearFocus() } }
            .verticalScroll(rememberScrollState())
    ) {
        Text(
            "คำนวณ Dose",
            style = MaterialTheme.typography.titleLarge,
            fontWeight = FontWeight.Bold
        )
        HorizontalDivider()
        Spacer(Modifier.height(8.dp))
        GenericDrugLabel(selectedDrug.name, selectedDrug.tradeName, department)
        Spacer(Modifier.height(8.dp))
        OutlinedTextField(
            value = weightStr,
            onValueChange = { weightStr = it },
            label = { Text("น้ำหนัก(kg)") },
            keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Decimal),
            modifier = Modifier.fillMaxWidth(),
            colors = textFieldColors
        )
        Spacer(Modifier.height(12.dp))

        OutlinedTextField(
            value = prescribeInputStr,
            onValueChange = { prescribeInputStr = it },
            label = { Text("prescribe (${selectedDrug.prescribeUnit})") },
            keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Decimal),
            modifier = Modifier.fillMaxWidth(),
            colors = textFieldColors
        )
        Spacer(Modifier.height(12.dp))

        Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(8.dp)) {
            OutlinedTextField(
                value = volumeStr,
                onValueChange = { volumeStr = it },
                label = { Text("ปริมาณสารน้ำ (ml)") },
                keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Decimal),
                modifier = Modifier.weight(1f),
                colors = textFieldColors
            )
            OutlinedTextField(
                value = rateStr,
                onValueChange = { rateStr = it },
                label = { Text("Rate (ml/hr)") },
                keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Decimal),
                modifier = Modifier.weight(1f),
                colors = textFieldColors
            )
        }

        Spacer(Modifier.height(16.dp))
        Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(8.dp)) {
            Button(
                onClick = { showDialog = true },
                modifier = Modifier.weight(1f),
                enabled = result.isAllDataPresent
            ) {
                Text("คำนวณผลลัพธ์")
            }
            OutlinedButton(onClick = { showTable = !showTable }, modifier = Modifier.weight(1f)) {
                Text(text = if (showTable) "ซ่อนตาราง" else "ดูตารางเพิ่มลดยา")
            }
        }
        if (showTable) {
            if (department == Department.Newborn) {
                NewbornRateDoseTable(
                    selectedDrug.toNewbornDrug(),
                    selectedUnit,
                    weight,
                    volume,
                    result.rate,
                    result.displayPrescribe
                )
            } else {
                PediatricRateDoseTable(
                    selectedDrug.toPediatricDrug(),
                    selectedUnit,
                    weight,
                    volume,
                    result.rate,
                    result.displayPrescribe
                )
            }
        }

        if (showDialog) {
            DoseResultDialog(
                result,
                selectedDrug,
                prescribeInput,
                volume,
                rate,
                onDismiss = { showDialog = false })
        }
    }
}

@Composable
fun DoseResultDialog(
    result: CalculationResultAdapter,
    selectedDrug: Drug,
    prescribeInput: Double,
    volume: Double,
    rate: Double,
    onDismiss: () -> Unit
) {
    AlertDialog(
        onDismissRequest = onDismiss,
        title = { Text("Order", fontWeight = FontWeight.Bold) },
        text = {
            // ดึง Style เดิมมาใช้ให้เหมือนกันทั้งแอป
            val textWeight = FontWeight.Normal
            val textDeco = TextDecoration.Underline
            val textSize = 1.1.em

            Column {
                // --- 1. ส่วนหัว Order ---
                Text(buildAnnotatedString {
                    append("${selectedDrug.name} (")
                    withStyle(
                        SpanStyle(
                            fontWeight = FontWeight.Bold,
                            textDecoration = textDeco,
                            fontSize = textSize
                        )
                    ) {
                        // 💡 นำ Dose ที่คำนวณได้มาแสดง
                        val doseVal =
                            if (result.displayDose > 0) formatValue(result.displayDose, 2) else "0"
                        append(doseVal)
                    }
                    append(" ")
                    withStyle(
                        SpanStyle(
                            fontWeight = FontWeight.Bold,
                            textDecoration = textDeco,
                            fontSize = textSize
                        )
                    ) { append(result.selectedUnit) }
                    append(")")
                })

                // --- 2. ส่วนเนื้อหา Order ---
                Text(
                    buildAnnotatedString {
                        withStyle(SpanStyle(fontWeight = textWeight)) {
                            // 💡 ใช้ prescribeInput ที่พยาบาลกรอก
                            append("$prescribeInput ${selectedDrug.prescribeUnit}")
                        }
                        // 💡 ใช้ volume ที่พยาบาลกรอก
                        append(" + D5W up to $volume ml\n")
                        withStyle(SpanStyle(fontWeight = textWeight)) {
                            // 💡 ใช้ rate ที่พยาบาลกรอก
                            append("IV drip: $rate ml/hr")
                        }
                    },
                    modifier = Modifier.padding(vertical = 4.dp)
                )

                HorizontalDivider(Modifier.padding(vertical = 12.dp), thickness = 0.5.dp)

                // --- 3. ส่วนแจ้งเตือนความเข้มข้น ---
                Row(verticalAlignment = Alignment.CenterVertically) {
                    Text(
                        "ควรระวัง",
                        style = MaterialTheme.typography.titleLarge,
                        color = MaterialTheme.colorScheme.error,
                        fontWeight = FontWeight.Bold
                    )
                }

                Spacer(Modifier.height(4.dp))

                Text(
                    "ความเข้มข้น: ${formatValue(result.displayConc, 2)} ${selectedDrug.concUnit}"
                )

                if (result.isConcOverCentral) {
                    val concLabel =
                        if (selectedDrug.maxConcPeripheral == null) "ความเข้มข้นเกิน!" else "ความเข้มข้น Central line เกิน!"
                    Text(
                        "$concLabel (Max: ${selectedDrug.maxConcCentral} ${selectedDrug.concUnit})",
                        color = Color.Red,
                        fontWeight = FontWeight.Bold,
                        style = MaterialTheme.typography.bodySmall
                    )
                } else if (result.displayDose > 0) {
                    val concLabel =
                        if (selectedDrug.maxConcPeripheral == null) "ความเข้มข้นเหมาะสม" else "ความเข้มข้น Central line เหมาะสม"
                    Text(
                        "$concLabel (Max: ${selectedDrug.maxConcCentral} ${selectedDrug.concUnit})",
                        color = Color(0xFF2E7D32),
                        style = MaterialTheme.typography.bodySmall
                    )
                }

                selectedDrug.maxConcPeripheral?.let { maxP ->
                    if (result.isConcOverPeripheral) {
                        Text(
                            "ความเข้มข้น Peripheral line เกิน! (Max: $maxP ${selectedDrug.concUnit})",
                            color = Color.Red,
                            fontWeight = FontWeight.Bold,
                            style = MaterialTheme.typography.bodySmall
                        )
                    } else if (result.displayDose > 0) {
                        Text(
                            "ความเข้มข้น Peripheral line เหมาะสม (Max: $maxP ${selectedDrug.concUnit})",
                            color = Color(0xFF2E7D32),
                            style = MaterialTheme.typography.bodySmall
                        )
                    }
                }

                Spacer(Modifier.height(8.dp))

                // --- 4. ส่วนสรุป Dose ---
                Text(buildAnnotatedString {
                    append("ขนาดยา:")
                    val doseColor = if (result.isDoseOver) Color.Red else Color.Unspecified
                    withStyle(SpanStyle(fontWeight = textWeight, color = doseColor)) {
                        val doseVal =
                            if (result.displayDose > 0) formatValue(result.displayDose, 2) else "0"
                        append("$doseVal ${result.selectedUnit}")
                    }
                })

                if (result.displayDose > 0) {
                    val isMinUnit = result.selectedUnit.contains("min")
                    val statusTextColor = if (!isMinUnit) Color.Red else Color.Unspecified
                    val statusTextStyle = if (!isMinUnit) FontWeight.Bold else FontWeight.Normal
                    val currentColor = when {
                        result.isDoseOver -> Color.Red
                        result.isDoseUnder -> Color(0xFFFFA500)
                        else -> Color(0xFF2E7D32)
                    }
                    val currentStyle = when {
                        result.isDoseOver -> FontWeight.Bold
                        result.isDoseUnder -> FontWeight.Bold
                        else -> textWeight
                    }
                    val statusMessage = buildAnnotatedString {
                        withStyle(SpanStyle(color = currentColor, fontWeight = currentStyle)) {
                            when {
                                result.isDoseOver -> {
                                    append(
