    val weight = weightStr.toDoubleOrNull() ?: 0.0
    val doseInput = doseInputStr.toDoubleOrNull() ?: 0.0
    val prescribeInput = prescribeInputStr.toDoubleOrNull() ?: 0.0
    val rate = rateStr.toDoubleOrNull() ?: 0.0

    val result =
        remember(selectedDrug, selectedUnit, weight, doseInput, prescribeInput, rate, department) {
            if (department == Department.Newborn) {
                NewbornCalculator.NewbornCalcVolumeScreen(
                    selectedDrug.toNewbornDrug(),
                    selectedUnit,
                    weight,
                    doseInput,
                    prescribeInput,
                    rate
                ).toAdapter()
            } else {
                PediatricCalculator.PediatricCalcVolumeScreen(
                    selectedDrug.toPediatricDrug(),
                    selectedUnit,
                    weight,
                    doseInput,
                    prescribeInput,
                    rate
                ).toAdapter()
            }
        }

    LaunchedEffect(selectedDrug) {
        weightStr = " "; doseInputStr = " "; prescribeInputStr = " "; rateStr = " "
    }

    val textFieldColors = OutlinedTextFieldDefaults.colors(
        focusedContainerColor = Color.White,
        unfocusedContainerColor = Color.White,
        errorContainerColor = Color(0xFFFFEBEE)
    )

    Column(
        modifier = Modifier.padding(4.dp).fillMaxSize()
            .windowInsetsPadding(WindowInsets.systemBars)
            .pointerInput(Unit) { detectTapGestures { focusManager.clearFocus() } }
