            label = { Text("น้ำหนัก(kg)") },
            keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Decimal),
            modifier = Modifier.fillMaxWidth(),
            colors = textFieldColors
        )
        Spacer(Modifier.height(12.dp))

        OutlinedTextField(
            value = doseInputStr,
            onValueChange = { doseInputStr = it },
            label = { Text("ขนาดยา (${if (selectedUnit.isBlank()) "เลือกหน่วยก่อน" else selectedUnit})") },
            keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Decimal),
            modifier = Modifier.fillMaxWidth(),
            colors = textFieldColors,
            isError = result.isDoseOver,
            textStyle = LocalTextStyle.current.copy(color = if (result.isDoseOver) Color.Red else Color.Unspecified)
        )
        Spacer(Modifier.height(8.dp))
        if (result.isDoseOver) Text(
            "ขนาดยาเกิน (Max: ${
                formatValue(
                    result.displayMaxDose,
                    2
                )
            } ${result.selectedUnit})",
            color = Color.Red,
            style = MaterialTheme.typography.bodySmall
        )
        if (result.isDoseUnder) Text(
            "ขนาดยาน้อยกว่าแนะนำ (Min: ${
                formatValue(
                    result.displayMinDose,
                    2
                )
            } ${result.selectedUnit})",
            color = Color(0xFFFFA500),
            style = MaterialTheme.typography.bodySmall
        )

        Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(8.dp)) {
            OutlinedTextField(
                value = prescribeInputStr,
                onValueChange = { prescribeInputStr = it },
                label = { Text("prescribe (${selectedDrug.prescribeUnit})") },
                keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Decimal),
                modifier = Modifier.weight(1f),
                colors = textFieldColors
            )
            OutlinedTextField(
                value = rateStr,
                onValueChange = { rateStr = it },
                label = { Text("Rate (ml/hr)") },
                keyboardOptions = KeyboardOptions(keyboardType = KeyboardType.Decimal),
                modifier = Modifier.weight(1f),
                colors = textFieldColors
            )
        }

        Spacer(Modifier.height(16.dp))

        Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(8.dp)) {
            Button(
                onClick = { showDialog = true },
                modifier = Modifier.weight(1f),
                enabled = result.isAllDataPresent
            ) {
                Text("คำนวณผลลัพธ์")
            }
            OutlinedButton(onClick = { showTable = !showTable }, modifier = Modifier.weight(1f)) {
                Text(text = if (showTable) "ซ่อนตาราง" else "ดูตารางเพิ่มลดยา")
            }
        }
        if (showTable) {
            if (department == Department.Newborn) {
                NewbornRateDoseTable(
                    selectedDrug.toNewbornDrug(),
                    selectedUnit,
                    weight,
                    result.volumeMl,
                    result.rate,
                    result.displayPrescribe
                )
            } else {
                PediatricRateDoseTable(
                    selectedDrug.toPediatricDrug(),
                    selectedUnit,
                    weight,
                    result.volumeMl,
                    result.rate,
                    result.displayPrescribe
                )
            }
        }

        if (showDialog) {
            VolumeResultDialog(
                result,
                selectedDrug,
                doseInput,
                prescribeInput,
                rate,
                onDismiss = { showDialog = false })
        }
    }
}

