@Composable
fun GenericCalcRuleOfSixScreen(selectedDrug: Drug, selectedUnit: String, department: Department) {
    val focusManager = LocalFocusManager.current
    var showDialog by remember { mutableStateOf(false) }
    var showTable by remember { mutableStateOf(false) }
    var weightStr by remember { mutableStateOf(" ") }
    var doseStr by remember { mutableStateOf(" ") }
    var volumeMlStr by remember { mutableStateOf(selectedDrug.defaultVolume.toString()) }

    val weight = weightStr.toDoubleOrNull() ?: 0.0
    val doseInput = doseStr.toDoubleOrNull() ?: 0.0
    val volumeMl = volumeMlStr.toDoubleOrNull() ?: 0.0

    val result = remember(selectedDrug, selectedUnit, weight, doseInput, volumeMl) {
        NewbornCalculator.NewbornCalcRuleofSixScreen(
            selectedDrug.toNewbornDrug(),
            selectedUnit,
            weight,
            doseInput,
            volumeMl
        ).toAdapter()
    }

    val dosePer1Ml = remember(selectedDrug, volumeMl) {
        if (volumeMl > 0 && selectedDrug.factor > 0) {
            val dummy = NewbornCalculator.NewbornCalcRuleofSixScreen(
                selectedDrug.toNewbornDrug(),
                selectedUnit,
                1.0,
                1.0,
                volumeMl
            )
            if (dummy.rate > 0) 1.0 / dummy.rate else 0.0
        } else {
            0.0
        }
    }

    LaunchedEffect(selectedDrug) {
        weightStr = " "; doseStr = " "; volumeMlStr = selectedDrug.defaultVolume.toString()
        showTable = false
    }

    val textFieldColors = OutlinedTextFieldDefaults.colors(
        focusedContainerColor = Color.White,
