                PediatricRateDoseTable(
                    selectedDrug.toPediatricDrug(),
                    selectedUnit,
                    weight,
                    result.volumeMl,
                    result.rate,
                    result.displayPrescribe
                )
            }
        }

        if (showDialog) {
            RuleOfSixResultDialog(
                result,
                selectedDrug,
                doseInput,
                volumeMl,
                onDismiss = { showDialog = false })
        }
    }
}

@Composable
fun RuleOfSixResultDialog(
    result: CalculationResultAdapter,
    selectedDrug: Drug,
    doseInput: Double,
    volumeMl: Double,
    onDismiss: () -> Unit
) {
    AlertDialog(
        onDismissRequest = onDismiss,
        title = { Text("Order", fontWeight = FontWeight.Bold) },
        text = {
            // ดึง Style เดิมมาใช้ให้เหมือนกันทั้งแอป
            val textWeight = FontWeight.Normal
            val textDeco = TextDecoration.Underline
            val textSize = 1.1.em

            Column {
                // --- 1. ส่วนหัว Order ---
                Text(buildAnnotatedString {
                    val displayName =
                        if (selectedDrug.tradeName.isNullOrBlank()) selectedDrug.name else "${selectedDrug.name} (${selectedDrug.tradeName})"
                    append("$displayName (")
                    withStyle(
                        SpanStyle(
                            fontWeight = textWeight,
                            textDecoration = textDeco,
                            fontSize = textSize
                        )
                    ) {
                        append("$doseInput")
                    }
                    append(" ")
                    withStyle(
                        SpanStyle(
                            fontWeight = textWeight,
                            textDecoration = textDeco,
                            fontSize = textSize
                        )
                    ) { append(result.selectedUnit) }
                    append(")")
                })

                // --- 2. ส่วนเนื้อหา Order ---
                Text(
                    buildAnnotatedString {
                        withStyle(SpanStyle(fontWeight = FontWeight.Bold)) {
                            append(
                                "${
                                    formatValue(
                                        result.displayPrescribe,
                                        2
                                    )
                                } ${selectedDrug.prescribeUnit}"
                            )
                        }
                        append(" + D5W up to $volumeMl ml\n")
                        withStyle(SpanStyle(fontWeight = FontWeight.Bold)) {
                            append("IV drip: ${formatValue(result.rate, 2)} ml/hr")
                        }
                    },
                    modifier = Modifier.padding(vertical = 4.dp)
                )

                HorizontalDivider(Modifier.padding(vertical = 12.dp), thickness = 0.5.dp)

                // --- 3. ส่วนแจ้งเตือนความเข้มข้น ---
                Row(verticalAlignment = Alignment.CenterVertically) {
                    Text(
                        "ควรระวัง",
                        style = MaterialTheme.typography.titleLarge,
                        color = MaterialTheme.colorScheme.error,
                        fontWeight = FontWeight.Bold
                    )
                }

                Spacer(Modifier.height(4.dp))

                Text(
                    "ความเข้มข้น: ${formatValue(result.displayConc, 2)} ${selectedDrug.concUnit}"
                )

                if (result.isConcOverCentral) {
                    val concLabel =
                        if (selectedDrug.maxConcPeripheral == null) "ความเข้มข้นเกิน!" else "ความเข้มข้น Central line เกิน!"
                    Text(
                        "$concLabel (Max: ${selectedDrug.maxConcCentral} ${selectedDrug.concUnit})",
                        color = Color.Red,
                        fontWeight = FontWeight.Bold,
                        style = MaterialTheme.typography.bodySmall
                    )
                } else if (doseInput > 0) {
                    val concLabel =
                        if (selectedDrug.maxConcPeripheral == null) "ความเข้มข้นเหมาะสม" else "ความเข้มข้น Central line เหมาะสม"
                    Text(
                        "$concLabel (Max: ${selectedDrug.maxConcCentral} ${selectedDrug.concUnit})",
                        color = Color(0xFF2E7D32),
                        style = MaterialTheme.typography.bodySmall
                    )
                }

                selectedDrug.maxConcPeripheral?.let { maxP ->
                    if (result.isConcOverPeripheral) {
                        Text(
                            "ความเข้มข้น Peripheral line เกิน! (Max: $maxP ${selectedDrug.concUnit})",
                            color = Color.Red,
                            fontWeight = FontWeight.Bold,
                            style = MaterialTheme.typography.bodySmall
                        )
                    } else if (doseInput > 0) {
                        Text(
                            "ความเข้มข้น Peripheral line เหมาะสม (Max: $maxP ${selectedDrug.concUnit})",
                            color = Color(0xFF2E7D32),
                            style = MaterialTheme.typography.bodySmall
                        )
                    }
                }

                Spacer(Modifier.height(8.dp))

                // --- 4. ส่วนสรุป Dose ---
                Text(buildAnnotatedString {
                    append("ขนาดยา:")
                    val doseColor = if (result.isDoseOver) Color.Red else Color.Unspecified
                    withStyle(SpanStyle(fontWeight = textWeight, color = doseColor)) {
                        val doseVal =
                            if (result.displayDose > 0) formatValue(result.displayDose, 2) else " "
                        append("$doseVal ${result.selectedUnit}")
                    }
                })

                if (result.displayDose > 0) {
                    val isMinUnit = result.selectedUnit.contains("min")
                    val statusTextColor = if (!isMinUnit) Color.Red else Color.Unspecified
                    val statusTextStyle = if (!isMinUnit) FontWeight.Bold else FontWeight.Normal
                    val currentColor = when {
                        result.isDoseOver -> Color.Red
                        result.isDoseUnder -> Color(0xFFFFA500)
                        else -> Color(0xFF2E7D32)
                    }
                    val currentStyle = when {
                        result.isDoseOver -> FontWeight.Bold
                        result.isDoseUnder -> FontWeight.Bold
                        else -> textWeight
                    }
                    val statusMessage = buildAnnotatedString {
                        withStyle(SpanStyle(color = currentColor, fontWeight = currentStyle)) {
                            when {
                                result.isDoseOver -> {
                                    append(
                                        "ขนาดยาเกิน! (Max: ${
                                            formatValue(
                                                result.displayMaxDose,
                                                2
                                            )
                                        }"
                                    )
                                }

                                result.isDoseUnder -> {
                                    append(
                                        "ขนาดยาน้อยกว่าแนะนำ (Min: ${
                                            formatValue(
                                                result.displayMinDose,
                                                2
                                            )
                                        }"
                                    )
                                }

                                else -> {
                                    append("ขนาดยาเหมาะสม (${result.displayMinDose} - ${result.displayMaxDose}")
                                }
                            }
                        }
                        append("\n")
                        withStyle(
                            SpanStyle(
                                color = currentColor,
                                fontWeight = currentStyle,
                                textDecoration = textDeco,
                                fontSize = textSize
                            )
                        ) {
                            append("${result.selectedUnit})")
                        }
                    }

                    Text(
                        text = statusMessage,
                        modifier = Modifier.fillMaxWidth().padding(vertical = 4.dp),
                        style = MaterialTheme.typography.bodyMedium,
                        lineHeight = 20.sp
                    )
                }
            }
        },
        confirmButton = {
            Button(onClick = onDismiss) {
                Text("ตกลง", fontWeight = FontWeight.Bold)
            }
        }
    )
}
