package org.chiangmeng.hadpediatric

import kotlinx.serialization.Serializable
import kotlinx.serialization.SerialName

@Serializable
data class NewbornDrug(
    val name: String,
    val tradeName: String? = null,
    @SerialName("maxConc")
    val maxConc: Double,
    val concUnit: String,
    val maxConcPeripheral: Double? = null,
    val minDose: Double,
    val maxDose: Double,
    val unit: String,
    val unit2: String? = null,
    val Multiply: Double,
    val DefaultVolumn: Double,
    val prescribeUnit: String
) {
    val maxConcCentral: Double get() = maxConc
}

val NewbornDrugList = NewbornDrugData.NewborndrugList

data class NewbornCalculationResult(
    val rate: Double = 0.0,
    val displayConc: Double = 0.0,
    val prescribeMg: Double = 0.0,
    val isDoseOver: Boolean = false,
    val isDoseUnder: Boolean = false,
    val isConcOverCentral: Boolean = false,
    val isMcgUnit: Boolean = false,
    val isMinUnit: Boolean = false,
    val prescribeMcgUnitFactor: Double = 1.0,
    val displayPrescribe: Double = 0.0,
    val concUnitFactor: Double = 1.0,
    val calculatedConc: Double = 0.0,
    val doseForMaxConc: Double = 0.0,
    val timeFactor: Double = 1.0,
    val weight: Double = 0.0,
    val dose: Double = 0.0,
    val volumeMl: Double = 0.0,
    val isConcOverPeripheral: Boolean = false,
    val doseForMaxPeripheralConc: Double = 0.0,
    val isAllDataPresent: Boolean = false,
    val isConflict: Boolean = false,
    val errorMessage: String = "",
    val displayDose: Double = 0.0,
    val selectedUnit: String = "",
    val baseMaxDose: Double = 0.0, // ค่า Max จาก DB
    val baseMinDose: Double = 0.0, // ค่า Min จาก DB
    val baseUnit: String = ""      // หน่วยหลักจาก DB
){
    // 🌟 สมองส่วนแสดงผลที่สมบูรณ์ 100% (คำนวณทั้งมวลยาและเวลา)
    private val conversionRatio: Double get() {
        if (selectedUnit.isBlank() || baseUnit.isBlank()) return 1.0

        // 1. แฟกเตอร์ของมวลยา (mcg = 1000, mg = 1)
        val currentMcg = if (selectedUnit.lowercase().contains("mcg")) 1000.0 else 1.0
        val baseMcg = if (baseUnit.lowercase().contains("mcg")) 1000.0 else 1.0

        // 2. แฟกเตอร์ของเวลา (min = 60, hr = 1)
        val currentMin = if (selectedUnit.lowercase().contains("min")) 60.0 else 1.0
        val baseMin = if (baseUnit.lowercase().contains("min")) 60.0 else 1.0

        // 3. สูตรแปลงหน่วยข้ามไปมา (ได้ทั้ง mcg -> mg, min -> hr และสลับกัน)
        return (currentMcg / baseMcg) * (baseMin / currentMin)
    }

    val displayMaxDose: Double get() = baseMaxDose * conversionRatio
    val displayMinDose: Double get() = baseMinDose * conversionRatio
}

object NewbornCalculator {

    private fun getFactors(selectedUnit: String): Triple<Double, Double, Double> {
        val unitLower = selectedUnit.lowercase()

        // เช็คหน่วย Dose (mcg vs mg)
        val doseUnitFactor = if (
            unitLower.contains("mcg") ||
            unitLower.contains("ug") ||
            unitLower.contains("µg")
        ) 1000.0 else 1.0

        // เช็คหน่วยเวลา (min vs hr)
        val timeFactor = if (unitLower.contains("min")) 60.0 else 1.0

        // เช็คหน่วยน้ำหนัก (/kg)
        val kgFactor = if (unitLower.contains("/kg")) 1.0 else 0.0

        return Triple(doseUnitFactor, timeFactor, kgFactor)
    }

    fun NewbornCalcRuleofSixScreen(
        selectedDrug: NewbornDrug,
        selectedUnit: String,
        weight: Double,
        doseInput: Double,
        volumeMl: Double
    ): NewbornCalculationResult {
        val (doseUnitFactor, timeFactor, kgFactor) = getFactors(selectedUnit)
        val (baseUnitFactor, baseTimeFactor, _) = getFactors(selectedDrug.unit)
        val doseToCompare = (doseInput / doseUnitFactor) * baseUnitFactor * (timeFactor / baseTimeFactor)
        val isDoseOver = doseInput > 0 && compare(doseToCompare, selectedDrug.maxDose, true, 1)
        val isDoseUnder = doseInput > 0 && compare(doseToCompare, selectedDrug.minDose, false, 1)
        val weightFactor = if (kgFactor > 0) weight else 1.0
        
        val isPrescribeMcgUnit = selectedDrug.prescribeUnit.contains("mcg")
        val prescribeMcgUnitFactor = if (isPrescribeMcgUnit) 1000.0 else 1.0
        
        val prescribeMg = selectedDrug.Multiply * weightFactor / prescribeMcgUnitFactor
        val displayPrescribe = prescribeMg * prescribeMcgUnitFactor
        val calculatedConc = if (volumeMl > 0) prescribeMg / volumeMl else 0.0
        
        val isMcgConcUnit = selectedDrug.concUnit.contains("mcg")
        val concUnitFactor = if (isMcgConcUnit) 1000.0 else 1.0
        val displayConc = calculatedConc * concUnitFactor
        
        val doseMgHr = (doseInput * weightFactor * timeFactor) / doseUnitFactor
        val rate = if (calculatedConc > 0) doseMgHr / calculatedConc else 0.0

        val maxConcMgMl = selectedDrug.maxConc / concUnitFactor
        val maxConcPeripheralMgMl = (selectedDrug.maxConcPeripheral ?: 0.0) / concUnitFactor

        val isConcOverCentral = compare(calculatedConc, maxConcMgMl, true, 1)
        val isConcOverPeripheral = maxConcPeripheralMgMl > 0 && compare(calculatedConc, maxConcPeripheralMgMl, true, 1)

        return NewbornCalculationResult(
            rate = rate,
            displayConc = displayConc,
            prescribeMg = prescribeMg,
            isDoseOver = isDoseOver,
            isDoseUnder = isDoseUnder,
            isConcOverCentral = isConcOverCentral,
            isConcOverPeripheral = isConcOverPeripheral,
            isMinUnit = timeFactor > 1.0,
            prescribeMcgUnitFactor = prescribeMcgUnitFactor,
            displayPrescribe = displayPrescribe,
            concUnitFactor = concUnitFactor,
            calculatedConc = calculatedConc,
            timeFactor = timeFactor,
            dose = doseInput,
            displayDose = doseInput,
            volumeMl = volumeMl,
            weight = weight,
            isAllDataPresent = weight > 0 && doseInput > 0 && volumeMl > 0 && rate > 0,
            selectedUnit = selectedUnit,
            baseMaxDose = selectedDrug.maxDose,
            baseMinDose = selectedDrug.minDose,
            baseUnit = selectedDrug.unit
        )
    }

    fun NewbornCalcPrescribeScreen(
        selectedDrug: NewbornDrug,
        selectedUnit: String,
        weight: Double,
        doseInput: Double,
        rateHr: Double,
        volumeMl: Double
    ): NewbornCalculationResult {
        val (doseUnitFactor, timeFactor, kgFactor) = getFactors(selectedUnit)
        val (baseUnitFactor, baseTimeFactor, _) = getFactors(selectedDrug.unit)
        val doseToCompare = (doseInput / doseUnitFactor) * baseUnitFactor * (timeFactor / baseTimeFactor)
        val isDoseOver = doseInput > 0 && compare(doseToCompare, selectedDrug.maxDose, true, 1)
        val isDoseUnder = doseInput > 0 && compare(doseToCompare, selectedDrug.minDose, false, 1)
        val weightFactor = if (kgFactor > 0) weight else 1.0
        
        val isMcgConcUnit = selectedDrug.concUnit.contains("mcg")
        val concUnitFactor = if (isMcgConcUnit) 1000.0 else 1.0
        
        val hoursDouble = if (rateHr > 0) volumeMl / rateHr else 0.0
        val prescribeMg = (doseInput * weightFactor * timeFactor * hoursDouble) / doseUnitFactor
        val calculatedConc = if (volumeMl > 0) prescribeMg / volumeMl else 0.0
        val displayConc = calculatedConc * concUnitFactor

        val maxConcMgMl = selectedDrug.maxConc / concUnitFactor
        val maxConcPeripheralMgMl = (selectedDrug.maxConcPeripheral ?: 0.0) / concUnitFactor

        val isConcOverCentral = compare(calculatedConc, maxConcMgMl, true, 1)
        val isConcOverPeripheral = maxConcPeripheralMgMl > 0 && compare(calculatedConc, maxConcPeripheralMgMl, true, 1)

        val doseForMaxConc = if (weightFactor > 0) {
            roundDownWithTol((maxConcMgMl * rateHr * doseUnitFactor) / (weightFactor * timeFactor))
        } else 0.0

        val doseForMaxPeripheralConc = if (weightFactor > 0 && maxConcPeripheralMgMl > 0) {
            roundDownWithTol((maxConcPeripheralMgMl * rateHr * doseUnitFactor) / (weightFactor * timeFactor))
        } else 0.0

        val isPrescribeMcgUnit = selectedDrug.prescribeUnit.contains("mcg")
        val prescribeMcgUnitFactor = if (isPrescribeMcgUnit) 1000.0 else 1.0
        val displayPrescribe = prescribeMg * prescribeMcgUnitFactor

        return NewbornCalculationResult(
            rate = rateHr,
            displayConc = displayConc,
            prescribeMg = prescribeMg,
            isDoseOver = isDoseOver,
            isDoseUnder = isDoseUnder,
            isConcOverCentral = isConcOverCentral,
            isConcOverPeripheral = isConcOverPeripheral,
            isMinUnit = timeFactor > 1.0,
            prescribeMcgUnitFactor = prescribeMcgUnitFactor,
            displayPrescribe = displayPrescribe,
            concUnitFactor = concUnitFactor,
            calculatedConc = calculatedConc,
            doseForMaxConc = doseForMaxConc,
            doseForMaxPeripheralConc = doseForMaxPeripheralConc,
            timeFactor = timeFactor,
            dose = doseInput,
            displayDose = doseInput,
            volumeMl = volumeMl,
            weight = weight,
            isAllDataPresent = weight > 0 && doseInput > 0 && volumeMl > 0 && rateHr > 0,
            selectedUnit = selectedUnit,
            baseMaxDose = selectedDrug.maxDose,
            baseMinDose = selectedDrug.minDose,
            baseUnit = selectedDrug.unit
        )
    }

    fun NewbornCalcDoseScreen(
        selectedDrug: NewbornDrug,
        selectedUnit: String,
        weight: Double,
        prescribeInput: Double,
        rateHr: Double,
        volumeMl: Double
    ): NewbornCalculationResult {
        val (doseUnitFactor, timeFactor, kgFactor) = getFactors(selectedUnit)
        val weightFactor = if (kgFactor > 0) weight else 1.0
        
        val isMcgConcUnit = selectedDrug.concUnit.contains("mcg")
        val concUnitFactor = if (isMcgConcUnit) 1000.0 else 1.0
        
        val isPrescribeMcgUnit = selectedDrug.prescribeUnit.contains("mcg")
        val prescribeMcgUnitFactor = if (isPrescribeMcgUnit) 1000.0 else 1.0

        val prescribeMg = if (prescribeInput > 0) prescribeInput / prescribeMcgUnitFactor else 0.0
        val calculatedConc = if (volumeMl > 0) prescribeMg / volumeMl else 0.0
        val displayConc = calculatedConc * concUnitFactor

        val maxConcMgMl = selectedDrug.maxConc / concUnitFactor
        val maxConcPeripheralMgMl = (selectedDrug.maxConcPeripheral ?: 0.0) / concUnitFactor

        val isConcOverCentral = volumeMl > 0 && prescribeInput > 0 && compare(calculatedConc, maxConcMgMl, true, 1)
        val isConcOverPeripheral = volumeMl > 0 && prescribeInput > 0 && maxConcPeripheralMgMl > 0 && compare(calculatedConc, maxConcPeripheralMgMl, true, 1)

        val hoursDouble = if (rateHr > 0) volumeMl / rateHr else 0.0
        val calculatedDose = if (weightFactor > 0 && hoursDouble > 0) {
            (prescribeMg * doseUnitFactor) / (weightFactor * timeFactor * hoursDouble)
        } else {
            0.0
        }


        val (baseUnitFactor, baseTimeFactor, _) = getFactors(selectedDrug.unit)
        val doseToCompare = (calculatedDose / doseUnitFactor) * baseUnitFactor * (timeFactor / baseTimeFactor)
        val isDoseOver = calculatedDose > 0 && compare(doseToCompare, selectedDrug.maxDose, true, 1)
        val isDoseUnder = calculatedDose > 0 && compare(doseToCompare, selectedDrug.minDose, false, 1)


        val doseForMaxConc = if (weightFactor > 0) {
            roundDownWithTol((maxConcMgMl * rateHr * doseUnitFactor) / (weightFactor * timeFactor))
        } else 0.0
        val doseForMaxPeripheralConc = if (weightFactor > 0 && maxConcPeripheralMgMl > 0) {
            roundDownWithTol((maxConcPeripheralMgMl * rateHr * doseUnitFactor) / (weightFactor * timeFactor))
        } else 0.0

        return NewbornCalculationResult(
            rate = rateHr,
            displayConc = displayConc,
            prescribeMg = prescribeMg,
            isDoseOver = isDoseOver,
            isDoseUnder = isDoseUnder,
            isConcOverCentral = isConcOverCentral,
            isConcOverPeripheral = isConcOverPeripheral,
            isMcgUnit = doseUnitFactor > 1.0,
            isMinUnit = timeFactor > 1.0,
            prescribeMcgUnitFactor = prescribeMcgUnitFactor,
            displayPrescribe = prescribeInput,
            concUnitFactor = concUnitFactor,
            calculatedConc = calculatedConc,
            doseForMaxConc = doseForMaxConc,
            doseForMaxPeripheralConc = doseForMaxPeripheralConc,
            timeFactor = timeFactor,
            weight = weight,
            dose = calculatedDose,
            volumeMl = volumeMl,
            displayDose = calculatedDose,
            isAllDataPresent = weight > 0 && prescribeInput > 0 && volumeMl > 0 && rateHr > 0,
            selectedUnit = selectedUnit,
            baseMaxDose = selectedDrug.maxDose,
            baseMinDose = selectedDrug.minDose,
            baseUnit = selectedDrug.unit
        )
    }

    fun NewbornCalcVolumeScreen(
        selectedDrug: NewbornDrug,
        selectedUnit: String,
        weight: Double,
        doseInput: Double,
        prescribeInput: Double,
        rateHr: Double
    ): NewbornCalculationResult {
        val (doseUnitFactor, timeFactor, kgFactor) = getFactors(selectedUnit)
        val (baseUnitFactor, baseTimeFactor, _) = getFactors(selectedDrug.unit)
        val doseToCompare = (doseInput / doseUnitFactor) * baseUnitFactor * (timeFactor / baseTimeFactor)
        val isDoseOver = doseInput > 0 && compare(doseToCompare, selectedDrug.maxDose, true, 1)
        val isDoseUnder = doseInput > 0 && compare(doseToCompare, selectedDrug.minDose, false, 1)
        val weightFactor = if (kgFactor > 0) weight else 1.0
        
        val isPrescribeMcgUnit = selectedDrug.prescribeUnit.contains("mcg")
        val prescribeMcgUnitFactor = if (isPrescribeMcgUnit) 1000.0 else 1.0
        val isMcgConcUnit = selectedDrug.concUnit.contains("mcg")
        val concUnitFactor = if (isMcgConcUnit) 1000.0 else 1.0

        val prescribeMg = if (prescribeInput > 0) prescribeInput / prescribeMcgUnitFactor else 0.0

        val calculatedVolume = if (doseInput > 0 && weightFactor > 0 && timeFactor > 0 && rateHr > 0) {
            (prescribeMg * doseUnitFactor * rateHr) / (doseInput * weightFactor * timeFactor)
        } else {
            0.0
        }

        val calculatedConc = if (calculatedVolume > 0) prescribeMg / calculatedVolume else 0.0
        val displayConc = calculatedConc * concUnitFactor

        val maxConcMgMl = selectedDrug.maxConc / concUnitFactor
        val maxConcPeripheralMgMl = (selectedDrug.maxConcPeripheral ?: 0.0) / concUnitFactor

        val isConcOverCentral = calculatedVolume > 0 && prescribeInput > 0 && compare(calculatedConc, maxConcMgMl, true, 1)
        val isConcOverPeripheral = calculatedVolume > 0 && prescribeInput > 0 && maxConcPeripheralMgMl > 0 && compare(calculatedConc, maxConcPeripheralMgMl, true, 1)

        val doseForMaxConc = if (weightFactor > 0) {
            roundDownWithTol((maxConcMgMl * rateHr * doseUnitFactor) / (weightFactor * timeFactor))
        } else 0.0
        val doseForMaxPeripheralConc = if (weightFactor > 0 && maxConcPeripheralMgMl > 0) {
            roundDownWithTol((maxConcPeripheralMgMl * rateHr * doseUnitFactor) / (weightFactor * timeFactor))
        } else 0.0

        return NewbornCalculationResult(
            rate = rateHr,
            displayConc = displayConc,
            prescribeMg = prescribeMg,
            isDoseOver = isDoseOver,
            isDoseUnder = isDoseUnder,
            isConcOverCentral = isConcOverCentral,
            isConcOverPeripheral = isConcOverPeripheral,
            isMinUnit = timeFactor > 1.0,
            prescribeMcgUnitFactor = prescribeMcgUnitFactor,
            displayPrescribe = prescribeInput,
            concUnitFactor = concUnitFactor,
            calculatedConc = calculatedConc,
            doseForMaxConc = doseForMaxConc,
            doseForMaxPeripheralConc = doseForMaxPeripheralConc,
            timeFactor = timeFactor,
            weight = weight,
            dose = doseInput,
            volumeMl = calculatedVolume,
            displayDose = doseInput,
            isAllDataPresent = weight > 0 && doseInput > 0 && prescribeInput > 0 && rateHr > 0,
            selectedUnit = selectedUnit,
            baseMaxDose = selectedDrug.maxDose,
            baseMinDose = selectedDrug.minDose,
            baseUnit = selectedDrug.unit
        )
    }
}
