import androidx.compose.foundation.layout.*
import androidx.compose.foundation.lazy.LazyColumn
import androidx.compose.foundation.lazy.items
import androidx.compose.foundation.shape.RoundedCornerShape
import androidx.compose.material3.*
import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.input.pointer.PointerEventPass
import androidx.compose.ui.input.pointer.pointerInput
import androidx.compose.ui.input.pointer.positionChange
import androidx.compose.ui.text.TextStyle
import androidx.compose.ui.text.font.FontFamily
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.unit.dp
import androidx.compose.ui.unit.sp
import hadpediatric.composeapp.generated.resources.Res
import hadpediatric.composeapp.generated.resources.comicneue_bold
import hadpediatric.composeapp.generated.resources.comicneue_regular
import hadpediatric.composeapp.generated.resources.mali_bold
import hadpediatric.composeapp.generated.resources.mali_regular
import org.jetbrains.compose.resources.Font

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun ReferenceScreen(onBack: () -> Unit) {
    // --- 1. ประกาศ Template ---
    val AppFontFamily = FontFamily(
        Font(Res.font.mali_regular, FontWeight.Normal),
        Font(Res.font.mali_bold, FontWeight.Bold),
        Font(Res.font.comicneue_regular, FontWeight.Normal),
        Font(Res.font.comicneue_bold, FontWeight.Bold)
    )

    val MyTypography = Typography(
        bodyLarge = TextStyle(fontFamily = AppFontFamily, fontSize = 20.sp),
        bodyMedium = TextStyle(fontFamily = AppFontFamily, fontSize = 18.sp),
        bodySmall = TextStyle(fontFamily = AppFontFamily, fontSize = 16.sp),
        headlineMedium = TextStyle(fontFamily = AppFontFamily, fontWeight = FontWeight.Bold, fontSize = 28.sp),
    )

    MaterialTheme(typography = MyTypography) {
        Box(
            modifier = Modifier
                .fillMaxSize()
                .pointerInput(Unit) {
                    awaitEachGesture {
                        val down = awaitFirstDown(pass = PointerEventPass.Initial)
                        val startX = down.position.x
                        if (startX < 120f) {
                            var totalDragX = 0f
                            while (true) {
                                val event = awaitPointerEvent(pass = PointerEventPass.Initial)
                                val change = event.changes.firstOrNull() ?: break
                                if (change.pressed) {
                                    val dragAmount = change.positionChange().x
                                    totalDragX += dragAmount
                                    if (totalDragX > 80f) {
                                        change.consume()
                                        onBack()
                                        break
                                    }
                                } else {
                                    break
                                }
                            }
                        }
                    }
                }
        ) {
            Scaffold(
                topBar = {
                    CenterAlignedTopAppBar(
                        title = { Text("เอกสารอ้างอิง", style = MaterialTheme.typography.headlineMedium) },
                        colors = TopAppBarDefaults.centerAlignedTopAppBarColors(
                            containerColor = Color(0xFFFDFD96) // เหลืองพาสเทล
                        )
                    )
                },
                containerColor = Color(0xFFF5F5F5)
            ) { innerPadding ->
                LazyColumn(
                    modifier = Modifier
                        .fillMaxSize()
                        .padding(innerPadding),
                    contentPadding = PaddingValues(16.dp),
                    verticalArrangement = Arrangement.spacedBy(12.dp)
                ) {
                    val references = listOf(
                        "1. Phelps SJ, Hagemann TM, Lee KR, Thompson AJ. Pediatric Injectable drugs. 11th ed. American Society of Health-System Pharmacists 2018.",
                        "2. Wolters Kluwer. Lexidrug [Internet]. Hudson (OH): Wolters Kluwer Clinical Drug Information; 2026 [cited 2026 Feb 18]. Available from: https://online.lexi.com",
                        "3. American Society of Health-System Pharmacists (ASHP). Pediatric continuous infusion standards [Internet]. Bethesda (MD): ASHP; updated 2025 Sep [cited 2026 Feb 18]. Available from: https://www.ashp.org/standardize4safety",
                        "4. Porka K. Safety concentration of inotrope and vasopressor for peripheral venous administration in pediatric patients. Journal of the Medical Association of Thailand. 2022;105(Suppl 3): S138–S145.",
                        "5. Medical University of South Carolina. MUSC continuous infusion guidelines for pediatric intensive care unit (PICU) patients [Internet]. Charleston (SC): MUSC Drug Information Center; 2007 [cited 2026 Feb 18]. Available from: https://muschealth.org",
                        "6. Merative US L.P. (2026) NeoFaxReference; Micromedex (v.1.2.2-105[R]) [ ซอฟต์แวร์แอปพลิเคชันมือถือ] https://Micromedex.com"
                    )

                    items(references) { ref ->
                        ReferenceItem(text = ref)
                    }

                    item {
                        Button(
                            onClick = onBack,
                            modifier = Modifier
                                .fillMaxWidth()
                                .padding(vertical = 16.dp),
                            colors = ButtonDefaults.buttonColors(containerColor = Color(0xFFFDFD96)),
                            shape = RoundedCornerShape(12.dp)
                        ) {
                            Text("ย้อนกลับ", color = Color.Black, style = MaterialTheme.typography.bodyLarge)
                        }
                    }
                }
            }
        }
    }
}

@Composable
fun ReferenceItem(text: String) {
    Card(
        modifier = Modifier.fillMaxWidth(),
        colors = CardDefaults.cardColors(containerColor = Color.White),
        elevation = CardDefaults.cardElevation(defaultElevation = 2.dp),
        shape = RoundedCornerShape(12.dp)
    ) {
        Text(
            text = text,
            modifier = Modifier.padding(16.dp),
            style = MaterialTheme.typography.bodyMedium.copy(
                lineHeight = 24.sp
            ),
            color = Color.DarkGray
        )
    }
}
