package org.chiangmeng.hadpediatric

import kotlinx.serialization.Serializable
import kotlinx.serialization.SerialName

@Serializable
data class Drug(
    val name: String,
    val tradeName: String? = null,
    @SerialName("maxConc")
    val maxConcCentral: Double,
    val concUnit: String = "mg/ml",
    val maxConcPeripheral: Double? = null,
    val minDose: Double,
    val maxDose: Double,
    val unit: String,
    val unit2: String? = null,
    val factor: Double = 1.0, // Used for Newborn's Multiply
    val defaultVolume: Double = 25.0,
    val prescribeUnit: String,
    val department: Department? = null
)

data class DrugConfig(
    val name: String,
    val tradeName: String? = null,
    val minDose: Double,
    val maxDose: Double,
    val unit: String,
    val unit2: String? = null,
    val prescribeUnit: String,
    val concUnit: String,
    @SerialName("maxConc")
    val maxConc: Double,
    val maxConcPeripheral: Double? = null,
    val defaultVolume: Double = 25.0,
    val factor: Double = 1.0
)

data class DrugCalculation(
    val id: String,
    val config: DrugConfig,
    val weight: Double,
    val dose: Double,
    val volume: Double,
    val rate: Double = 0.0,
    val department: Department,
    val selectedUnit: String
) {
    private val newbornResult: NewbornCalculationResult? by lazy {
        if (department == Department.Newborn) {
            NewbornCalculator.NewbornCalcPrescribeScreen(
                config.toNewbornDrug(), selectedUnit, weight, dose, rate, volume
            )
        } else null
    }

    private val pediatricResult: PediatricCalculationResult? by lazy {
        if (department == Department.Pediatric) {
            PediatricCalculator.PediatricCalcPrescribeScreen(
                config.toPediatricDrug(), selectedUnit, weight, dose, rate, volume
            )
        } else null
    }

    val mlPerHour: Double 
        get() = newbornResult?.rate ?: pediatricResult?.rate ?: rate

    val displayPrescribeAmount: Double 
        get() = newbornResult?.displayPrescribe ?: pediatricResult?.displayPrescribe ?: 0.0

    val displayConcentration: Double 
        get() = newbornResult?.displayConc ?: pediatricResult?.displayConc ?: 0.0

    val isDoseOver: Boolean 
        get() = newbornResult?.isDoseOver ?: pediatricResult?.isDoseOver ?: false

    val isDoseUnder: Boolean 
        get() = newbornResult?.isDoseUnder ?: pediatricResult?.isDoseUnder ?: false

    val isConcOverCentral: Boolean 
        get() = newbornResult?.isConcOverCentral ?: pediatricResult?.isConcOverCentral ?: false

    val isConcOverPeripheral: Boolean 
        get() = newbornResult?.isConcOverPeripheral ?: pediatricResult?.isConcOverPeripheral ?: false
}

// Mapping extensions
fun DrugConfig.toNewbornDrug() = NewbornDrug(
    name = name,
    tradeName = tradeName,
    maxConc = maxConc,
    concUnit = concUnit,
    maxConcPeripheral = maxConcPeripheral,
    minDose = minDose,
    maxDose = maxDose,
    unit = unit,
    unit2 = unit2,
    Multiply = factor,
    DefaultVolumn = defaultVolume,
    prescribeUnit = prescribeUnit
)

fun DrugConfig.toPediatricDrug() = PediatricDrug(
    name = name,
    tradeName = tradeName,
    maxConc = maxConc,
    concUnit = concUnit,
    maxConcPeripheral = maxConcPeripheral,
    minDose = minDose,
    maxDose = maxDose,
    unit = unit,
    unit2 = unit2,
    DefaultVolume = defaultVolume,
    prescribeUnit = prescribeUnit
)

fun NewbornDrug.toDrug() = Drug(
    name = name,
    tradeName = tradeName,
    maxConcCentral = maxConc,
    concUnit = concUnit,
    maxConcPeripheral = maxConcPeripheral,
    minDose = minDose,
    maxDose = maxDose,
    unit = unit,
    unit2 = unit2,
    factor = Multiply,
    defaultVolume = DefaultVolumn,
    prescribeUnit = prescribeUnit,
    department = Department.Newborn
)

fun PediatricDrug.toDrug() = Drug(
    name = name,
    tradeName = tradeName,
    maxConcCentral = maxConc,
    concUnit = concUnit ?: "mg/ml",
    maxConcPeripheral = maxConcPeripheral,
    minDose = minDose,
    maxDose = maxDose,
    unit = unit,
    unit2 = unit2,
    factor = 1.0,
